{
  "name": "DeviceMaster Pro",
  "description": "A professional device management system for tracking corporate assets like laptops and mobile phones, featuring Excel import/export, dashboard analytics, and AI-powered insights."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum DeviceType {
  LAPTOP = 'Laptop',
  MOBILE = 'Mobile Phone',
  TABLET = 'Tablet',
  DESKTOP = 'Desktop',
  OTHER = 'Other'
}

export interface Device {
  id: string;
  type: DeviceType;
  manufacturer: string;
  model: string;
  serialNumber: string;
  purchaseDate: string;
  warrantyExpiry: string;
  handoverDate: string;
  assignedTo: string;
  status: 'Available' | 'Assigned' | 'Maintenance' | 'Retired';
  notes?: string;
}

export interface DashboardStats {
  totalDevices: number;
  assignedDevices: number;
  expiringWarranty: number;
  typeDistribution: { name: string; value: number }[];
}

import { Device } from '../types';

const STORAGE_KEY = 'device_master_data';

export const storageService = {
  getDevices: (): Device[] => {
    const data = localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  },

  saveDevices: (devices: Device[]): void => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(devices));
  },

  exportToCSV: (devices: Device[]) => {
    const headers = ['Type', 'Manufacturer', 'Model', 'Serial', 'Purchase Date', 'Warranty Expiry', 'Handover Date', 'Assigned To', 'Status'];
    const rows = devices.map(d => [
      d.type,
      d.manufacturer,
      d.model,
      d.serialNumber,
      d.purchaseDate,
      d.warrantyExpiry,
      d.handoverDate,
      d.assignedTo,
      d.status
    ]);

    const csvContent = [
      headers.join(','),
      ...rows.map(e => e.map(val => `"${val}"`).join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', `devices_export_${new Date().toISOString().split('T')[0]}.csv`);
    link.style.visibility = 'hidden';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  }
};

import { GoogleGenAI, Type } from "@google/genai";
import { Device } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const geminiService = {
  analyzeInventory: async (devices: Device[]) => {
    if (devices.length === 0) return "No data to analyze yet.";

    const deviceSummary = devices.map(d => 
      `${d.type} (${d.manufacturer} ${d.model}) - Serial: ${d.serialNumber}, Warranty: ${d.warrantyExpiry}`
    ).join('\n');

    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `As an IT Asset Manager, analyze this device inventory and provide 3-4 concise professional insights regarding maintenance, lifecycle management, or risks. Focus on upcoming warranty expirations or brand diversity. List them as bullet points. 

      Inventory:
      ${deviceSummary}`,
      config: {
        temperature: 0.7,
      }
    });

    return response.text || "Could not generate insights at this time.";
  }
};

import React, { useMemo } from 'react';
import { PieChart, Pie, Cell, ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Legend } from 'recharts';
import { Device, DeviceType } from '../types';
import { Monitor, Smartphone, ShieldAlert, CheckCircle } from 'lucide-react';

interface Props {
  devices: Device[];
}

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6'];

const Dashboard: React.FC<Props> = ({ devices }) => {
  const stats = useMemo(() => {
    const today = new Date();
    const threeMonthsFromNow = new Date();
    threeMonthsFromNow.setMonth(today.getMonth() + 3);

    const typeCounts: Record<string, number> = {};
    let assigned = 0;
    let expiring = 0;

    devices.forEach(d => {
      typeCounts[d.type] = (typeCounts[d.type] || 0) + 1;
      if (d.status === 'Assigned') assigned++;

      const expiry = new Date(d.warrantyExpiry);
      if (expiry > today && expiry < threeMonthsFromNow) expiring++;
    });

    const typeData = Object.entries(typeCounts).map(([name, value]) => ({ name, value }));

    return {
      total: devices.length,
      assigned,
      expiring,
      typeData
    };
  }, [devices]);

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard 
          icon={<Monitor className="text-blue-500" />} 
          title="Total Assets" 
          value={stats.total} 
          color="bg-blue-50" 
        />
        <StatCard 
          icon={<CheckCircle className="text-green-500" />} 
          title="Assigned" 
          value={stats.assigned} 
          color="bg-green-50" 
        />
        <StatCard 
          icon={<ShieldAlert className="text-amber-500" />} 
          title="Expiring Soon" 
          value={stats.expiring} 
          subtitle="Next 90 days"
          color="bg-amber-50" 
        />
        <StatCard 
          icon={<Smartphone className="text-purple-500" />} 
          title="Device Types" 
          value={stats.typeData.length} 
          color="bg-purple-50" 
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 h-[350px]">
          <h3 className="text-sm font-semibold text-slate-500 mb-4 uppercase tracking-wider">Asset Distribution</h3>
          <ResponsiveContainer width="100%" height="90%">
            <PieChart>
              <Pie
                data={stats.typeData}
                cx="50%"
                cy="50%"
                innerRadius={60}
                outerRadius={80}
                paddingAngle={5}
                dataKey="value"
              >
                {stats.typeData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Pie>
              <Tooltip />
              <Legend />
            </PieChart>
          </ResponsiveContainer>
        </div>

        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 h-[350px]">
          <h3 className="text-sm font-semibold text-slate-500 mb-4 uppercase tracking-wider">Device Count by Type</h3>
          <ResponsiveContainer width="100%" height="90%">
            <BarChart data={stats.typeData}>
              <XAxis dataKey="name" />
              <YAxis />
              <Tooltip />
              <Bar dataKey="value" fill="#3b82f6" radius={[4, 4, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

const StatCard = ({ icon, title, value, color, subtitle }: any) => (
  <div className={`${color} p-6 rounded-xl border border-slate-100 shadow-sm transition-transform hover:scale-[1.02]`}>
    <div className="flex items-center justify-between mb-2">
      <div className="p-2 bg-white rounded-lg shadow-sm">{icon}</div>
      <span className="text-2xl font-bold text-slate-800">{value}</span>
    </div>
    <div className="text-sm font-medium text-slate-600">{title}</div>
    {subtitle && <div className="text-xs text-slate-400 mt-1">{subtitle}</div>}
  </div>
);

export default Dashboard;

