import React, { useState, useEffect } from 'react';
import { Device, DeviceType, HistoryEntry } from './types';
import { storageService } from './services/storageService';
import { geminiService } from './services/geminiService';
import Dashboard from './components/Dashboard';
import DeviceTable from './components/DeviceTable';
import DeviceForm from './components/DeviceForm';
import HistoryModal from './components/HistoryModal';
import { Plus, Download, Sparkles, LayoutDashboard, Database, Settings, LogOut, Loader2 } from 'lucide-react';

const App: React.FC = () => {
  const [devices, setDevices] = useState<Device[]>([]);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'inventory'>('dashboard');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingDevice, setEditingDevice] = useState<Device | null>(null);
  const [historyDevice, setHistoryDevice] = useState<Device | null>(null);
  const [aiInsights, setAiInsights] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  useEffect(() => {
    const data = storageService.getDevices();
    if (data.length === 0) {
      const initialData: Device[] = [
        {
          id: '1',
          type: DeviceType.LAPTOP,
          manufacturer: 'Apple',
          model: 'MacBook Pro M2',
          serialNumber: 'SN12345678',
          purchaseDate: '2023-01-15',
          warrantyExpiry: '2025-01-15',
          handoverDate: '2023-01-20',
          assignedTo: 'Nguyen Van A',
          status: 'Assigned',
          history: [
            { id: 'h1', assignee: 'Kho IT', date: '2023-01-15', notes: 'Initial stock' },
            { id: 'h2', assignee: 'Nguyen Van A', date: '2023-01-20', notes: 'New joiner asset' }
          ]
        },
        {
          id: '2',
          type: DeviceType.MOBILE,
          manufacturer: 'Samsung',
          model: 'Galaxy S23',
          serialNumber: 'SM-G900-ABC',
          purchaseDate: '2023-05-10',
          warrantyExpiry: '2024-05-10',
          handoverDate: '',
          assignedTo: '',
          status: 'Available',
          history: [
            { id: 'h3', assignee: 'Kho IT', date: '2023-05-10', notes: 'Purchase' }
          ]
        }
      ];
      setDevices(initialData);
      storageService.saveDevices(initialData);
    } else {
      setDevices(data);
    }
  }, []);

  const saveDevice = (device: Device) => {
    let updatedDevices: Device[];

    if (editingDevice) {
      // Check for assignee change to record history
      const oldDevice = devices.find(d => d.id === device.id);
      const isAssigneeChanged = oldDevice && oldDevice.assignedTo !== device.assignedTo;

      const newHistory: HistoryEntry[] = [...(device.history || [])];
      if (isAssigneeChanged) {
        newHistory.push({
          id: Math.random().toString(36).substr(2, 9),
          assignee: device.assignedTo || 'Unassigned',
          date: device.handoverDate || new Date().toISOString().split('T')[0],
          notes: 'Assignment updated'
        });
      }

      const updatedDevice = { ...device, history: newHistory };
      updatedDevices = devices.map(d => d.id === device.id ? updatedDevice : d);
    } else {
      // New device: Initial history record
      const initialHistory: HistoryEntry[] = [{
        id: Math.random().toString(36).substr(2, 9),
        assignee: device.assignedTo || 'Initial Setup',
        date: device.purchaseDate || new Date().toISOString().split('T')[0],
        notes: 'First registration'
      }];
      updatedDevices = [...devices, { ...device, history: initialHistory }];
    }

    setDevices(updatedDevices);
    storageService.saveDevices(updatedDevices);
    setIsFormOpen(false);
    setEditingDevice(null);
  };

  const deleteDevice = (id: string) => {
    if (window.confirm('Are you sure you want to delete this asset?')) {
      const updated = devices.filter(d => d.id !== id);
      setDevices(updated);
      storageService.saveDevices(updated);
    }
  };

  const generateInsights = async () => {
    setIsAnalyzing(true);
    try {
      const insight = await geminiService.analyzeInventory(devices);
      setAiInsights(insight);
    } catch (error) {
      console.error(error);
      setAiInsights("Failed to generate insights.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="flex min-h-screen bg-slate-50">
      <aside className="hidden md:flex w-64 flex-col bg-white border-r border-slate-200 sticky top-0 h-screen">
        <div className="p-6">
          <div className="flex items-center gap-2 mb-8">
            <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white font-bold text-xl shadow-lg shadow-blue-200">
              D
            </div>
            <div>
              <h1 className="font-bold text-slate-800 leading-tight">DeviceMaster</h1>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest">Enterprise Pro</p>
            </div>
          </div>

          <nav className="space-y-1">
            <SidebarLink 
              active={activeTab === 'dashboard'} 
              onClick={() => setActiveTab('dashboard')}
              icon={<LayoutDashboard size={20} />}
              label="Overview"
            />
            <SidebarLink 
              active={activeTab === 'inventory'} 
              onClick={() => setActiveTab('inventory')}
              icon={<Database size={20} />}
              label="Inventory"
            />
            <SidebarLink 
              active={false} 
              onClick={() => {}}
              icon={<Settings size={20} />}
              label="Settings"
            />
          </nav>
        </div>

        <div className="mt-auto p-6 border-t border-slate-100">
          <button className="flex items-center gap-3 text-slate-500 hover:text-red-600 transition-colors px-4 py-2 w-full">
            <LogOut size={20} />
            <span className="font-medium">Logout</span>
          </button>
        </div>
      </aside>

      <main className="flex-1 overflow-y-auto">
        <header className="bg-white border-b border-slate-200 sticky top-0 z-30 px-6 py-4 flex items-center justify-between">
          <h2 className="text-xl font-bold text-slate-800">
            {activeTab === 'dashboard' ? 'Dashboard Overview' : 'Device Inventory'}
          </h2>

          <div className="flex items-center gap-3">
            <button 
              onClick={generateInsights}
              disabled={isAnalyzing}
              className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-purple-600 to-blue-600 text-white rounded-xl font-semibold text-sm shadow-md hover:shadow-lg transition-all disabled:opacity-50"
            >
              {isAnalyzing ? <Loader2 className="animate-spin" size={16} /> : <Sparkles size={16} />}
              AI Insights
            </button>
            <button 
              onClick={() => storageService.exportToCSV(devices)}
              className="p-2.5 bg-slate-100 text-slate-600 rounded-xl hover:bg-slate-200 transition-colors"
              title="Export to Excel (CSV)"
            >
              <Download size={20} />
            </button>
            <button 
              onClick={() => {
                setEditingDevice(null);
                setIsFormOpen(true);
              }}
              className="flex items-center gap-2 px-5 py-2.5 bg-blue-600 text-white rounded-xl font-bold text-sm shadow-lg shadow-blue-200 hover:bg-blue-700 transition-all active:scale-95"
            >
              <Plus size={18} />
              Add Device
            </button>
          </div>
        </header>

        <div className="p-6 max-w-7xl mx-auto space-y-6">
          {aiInsights && (
            <div className="bg-blue-50 border border-blue-100 p-6 rounded-2xl relative animate-in slide-in-from-top-4 duration-300">
              <button 
                onClick={() => setAiInsights(null)}
                className="absolute top-4 right-4 text-blue-400 hover:text-blue-600"
              >
                <Plus className="rotate-45" size={20} />
              </button>
