            <SidebarLink active={activeTab === 'inventory'} onClick={() => setActiveTab('inventory')} icon={<Database size={20} />} label="Asset Inventory" />
            <SidebarLink active={activeTab === 'settings'} onClick={() => setActiveTab('settings')} icon={<SettingsIcon size={20} />} label="Cloud Settings" />
          </nav>

