import React, { useState, useEffect } from 'react';
import { Device, DeviceType } from '../types';
import { X, Plus } from 'lucide-react';

interface Props {
  device?: Device | null;
  onSave: (device: Device) => void;
  onClose: () => void;
}

const DeviceForm: React.FC<Props> = ({ device, onSave, onClose }) => {
  const [formData, setFormData] = useState<Partial<Device>>({
    type: DeviceType.LAPTOP,
    manufacturer: '',
    model: '',
    serialNumber: '',
    purchaseDate: '',
    warrantyExpiry: '',
    handoverDate: '',
    assignedTo: '',
    status: 'Available',
    notes: ''
  });

  useEffect(() => {
    if (device) {
      setFormData(device);
    }
  }, [device]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    onSave({
      ...formData,
      id: device?.id || Math.random().toString(36).substr(2, 9),
      history: formData.history || []
    } as Device);
  };

  // Modern prominent input style: Dark background with prominent white text
  const inputBaseClass = "w-full px-4 py-3 bg-slate-900 text-white rounded-xl border border-slate-700 focus:ring-4 focus:ring-indigo-500/30 focus:border-indigo-500 outline-none transition-all font-semibold placeholder:text-slate-500 shadow-inner";
  const labelClass = "text-[11px] font-black text-slate-500 uppercase tracking-widest mb-1.5 block ml-1";

  return (
    <div className="fixed inset-0 bg-slate-950/70 backdrop-blur-md flex items-center justify-center z-50 p-4 overflow-y-auto">
