            <div>
              <label className={labelClass}>Device Type</label>
              <select 
                className={inputBaseClass}
                value={formData.type}
                onChange={e => setFormData({ ...formData, type: e.target.value as DeviceType })}
              >
                {Object.values(DeviceType).map(type => <option key={type} value={type} className="bg-slate-900">{type}</option>)}
              </select>
            </div>

            <div>
              <label className={labelClass}>Manufacturer</label>
              <input 
                required
                className={inputBaseClass}
                placeholder="e.g. Dell, Apple, Samsung"
                value={formData.manufacturer}
                onChange={e => setFormData({ ...formData, manufacturer: e.target.value })}
              />
            </div>

            <div>
              <label className={labelClass}>Model Name</label>
              <input 
                required
                className={inputBaseClass}
                placeholder="e.g. Latitude 5420, iPhone 15 Pro"
                value={formData.model}
                onChange={e => setFormData({ ...formData, model: e.target.value })}
              />
            </div>

            <div>
              <label className={labelClass}>Serial Number</label>
              <input 
                required
                className={inputBaseClass}
                placeholder="Unique Serial/Service Tag"
                value={formData.serialNumber}
                onChange={e => setFormData({ ...formData, serialNumber: e.target.value })}
              />
            </div>

            <div>
              <label className={labelClass}>Purchase Date</label>
              <input 
                type="date"
                required
                className={inputBaseClass}
                value={formData.purchaseDate}
                onChange={e => setFormData({ ...formData, purchaseDate: e.target.value })}
              />
            </div>

            <div>
              <label className={labelClass}>Warranty Expiry</label>
              <input 
                type="date"
                required
                className={inputBaseClass}
                value={formData.warrantyExpiry}
                onChange={e => setFormData({ ...formData, warrantyExpiry: e.target.value })}
              />
            </div>

            <div>
              <label className={labelClass}>Current Status</label>
              <select 
                className={inputBaseClass}
                value={formData.status}
                onChange={e => setFormData({ ...formData, status: e.target.value as any })}
              >
                <option value="Available" className="bg-slate-900">Available</option>
                <option value="Assigned" className="bg-slate-900">Assigned</option>
                <option value="Maintenance" className="bg-slate-900">Maintenance</option>
                <option value="Retired" className="bg-slate-900">Retired</option>
              </select>
            </div>

            <div>
              <label className={labelClass}>Assigned To</label>
              <input 
                className={inputBaseClass}
                placeholder="Employee Name"
                value={formData.assignedTo}
                onChange={e => setFormData({ ...formData, assignedTo: e.target.value })}
              />
