import React, { useState, useEffect, useRef } from 'react';
import { Device, DeviceType, HistoryEntry } from './types';
import { storageService } from './services/storageService';
import { geminiService } from './services/geminiService';
import { translations } from './translations';
import Dashboard from './components/Dashboard';
import DeviceTable from './components/DeviceTable';
import DeviceForm from './components/DeviceForm';
import HistoryModal from './components/HistoryModal';
import { 
  Plus, Download, Upload, Sparkles, LayoutDashboard, 
  Database, LogOut, Loader2, CheckCircle2, Cloud, 
  Settings as SettingsIcon, AlertCircle, RefreshCw, Languages 
} from 'lucide-react';

const App: React.FC = () => {
  const [lang, setLang] = useState<'en' | 'vi'>('en');
  const [devices, setDevices] = useState<Device[]>([]);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'inventory' | 'settings'>('dashboard');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingDevice, setEditingDevice] = useState<Device | null>(null);
  const [historyDevice, setHistoryDevice] = useState<Device | null>(null);
  const [aiInsights, setAiInsights] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [sheetUrl, setSheetUrl] = useState<string>(storageService.getSettings().sheetUrl);
  const [syncStatus, setSyncStatus] = useState<'idle' | 'success' | 'error'>('idle');

  const t = translations[lang];

  useEffect(() => {
    const loadInitialData = async () => {
      const localData = storageService.getDevicesLocal();
      if (localData.length > 0) setDevices(localData);
      if (sheetUrl) {
        handleSync('pull');
      }
    };
    loadInitialData();
  }, []);

  const toggleLanguage = () => setLang(prev => prev === 'en' ? 'vi' : 'en');

  const handleSync = async (direction: 'pull' | 'push', updatedDevices?: Device[]) => {
    if (!sheetUrl) return;
    setIsSyncing(true);
    setSyncStatus('idle');
    try {
      const targetData = updatedDevices || devices;
      const result = await storageService.syncWithGoogleSheet(sheetUrl, direction === 'push' ? targetData : undefined);
      if (direction === 'pull' && result) {
        setDevices(result);
        storageService.saveDevicesLocal(result);
      }
      setSyncStatus('success');
    } catch (error) {
      setSyncStatus('error');
    } finally {
      setIsSyncing(false);
    }
  };

  const saveDevice = async (newDeviceData: Device) => {
    const isDuplicateSerial = devices.some(d => 
      d.serialNumber.toLowerCase() === newDeviceData.serialNumber.toLowerCase() && 
      d.id !== newDeviceData.id
    );

    if (isDuplicateSerial) {
      alert(`Error: Serial Number "${newDeviceData.serialNumber}" already exists!`);
      return;
    }

    let updatedDevices: Device[];
    const now = new Date().toISOString().split('T')[0];

    if (editingDevice) {
      const isAssigneeChanged = editingDevice.assignedTo !== newDeviceData.assignedTo;
      const isStatusChanged = editingDevice.status !== newDeviceData.status;
      const newHistory: HistoryEntry[] = [...(newDeviceData.history || [])];

      if (isAssigneeChanged || isStatusChanged) {
        newHistory.push({
          id: Math.random().toString(36).substr(2, 9),
          assignee: newDeviceData.assignedTo || t.unassigned,
          date: newDeviceData.handoverDate || now,
          notes: isAssigneeChanged 
            ? `Handover: From "${editingDevice.assignedTo || 'Stock'}" to "${newDeviceData.assignedTo || 'New Owner'}"`
            : `Status update: ${newDeviceData.status}`
        });
      }

      const updatedDevice = { ...newDeviceData, history: newHistory };
      updatedDevices = devices.map(d => d.id === newDeviceData.id ? updatedDevice : d);
    } else {
      const initialHistory: HistoryEntry[] = [{
        id: Math.random().toString(36).substr(2, 9),
        assignee: newDeviceData.assignedTo || 'IT Stock',
        date: newDeviceData.purchaseDate || now,
        notes: 'Initial registration'
      }];
      updatedDevices = [...devices, { ...newDeviceData, history: initialHistory }];
    }

    setDevices(updatedDevices);
    storageService.saveDevicesLocal(updatedDevices);
    setIsFormOpen(false);
    setEditingDevice(null);

    if (sheetUrl) {
      handleSync('push', updatedDevices);
    }
  };

  const deleteDevice = (id: string) => {
    if (window.confirm('Delete this device permanently?')) {
      const updated = devices.filter(d => d.id !== id);
      setDevices(updated);
      storageService.saveDevicesLocal(updated);
      if (sheetUrl) handleSync('push', updated);
    }
  };

  const updateSheetUrl = (url: string) => {
    setSheetUrl(url);
    storageService.saveSettings({ sheetUrl: url });
  };

  const generateInsights = async () => {
    setIsAnalyzing(true);
    try {
      const insight = await geminiService.analyzeInventory(devices);
      setAiInsights(insight);
    } catch (error) {
      setAiInsights("AI Analysis failed. Please try again later.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="flex min-h-screen bg-slate-50">
      {/* Sidebar */}
      <aside className="hidden md:flex w-72 flex-col bg-slate-900 text-slate-300 sticky top-0 h-screen shadow-2xl">
        <div className="p-8">
          <div className="flex flex-col gap-1 mb-10 group">
             <div className="flex items-center gap-3">
                <div className="w-12 h-12 bg-rose-700 rounded-xl flex items-center justify-center text-white font-black text-2xl shadow-xl shadow-rose-900/50">
                  IK
                </div>
                <div>
                  <h1 className="font-black text-white text-xl leading-none tracking-tighter uppercase">INABATA</h1>
                  <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest mt-1">Device Master</p>
                </div>
             </div>
             <p className="mt-4 text-[10px] text-rose-500 font-bold uppercase tracking-[0.2em] opacity-80 pl-1">{t.subName}</p>
          </div>

          <nav className="space-y-2">
            <SidebarLink active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon={<LayoutDashboard size={20} />} label={t.dashboard} />
            <SidebarLink active={activeTab === 'inventory'} onClick={() => setActiveTab('inventory')} icon={<Database size={20} />} label={t.inventory} />
            <SidebarLink active={activeTab === 'settings'} onClick={() => setActiveTab('settings')} icon={<SettingsIcon size={20} />} label={t.settings} />
          </nav>

          <div className="mt-10 p-5 bg-black/30 rounded-2xl border border-slate-800">
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center gap-2 text-[10px] font-black text-slate-500 uppercase tracking-widest">
                <Cloud size={14} className={sheetUrl ? "text-green-500" : "text-rose-500"} />
                {t.cloudSync}
              </div>
              {isSyncing && <RefreshCw size={12} className="animate-spin text-rose-500" />}
            </div>
            {sheetUrl ? (
              <div className="space-y-2">
                <div className={`flex items-center gap-2 text-xs font-bold ${syncStatus === 'error' ? 'text-rose-400' : 'text-green-400'}`}>
                  {syncStatus === 'error' ? <AlertCircle size={14}/> : <CheckCircle2 size={14} />}
                  {syncStatus === 'error' ? t.syncFailed : t.connected}
                </div>
                <button 
                  onClick={() => handleSync('pull')}
                  disabled={isSyncing}
                  className="w-full mt-2 py-2 bg-slate-800 hover:bg-rose-700 hover:text-white rounded-xl text-[10px] font-black uppercase tracking-widest transition-all"
                >
                  {t.syncNow}
                </button>
              </div>
            ) : (
              <p className="text-[10px] text-slate-500 italic">Cloud storage not configured.</p>
            )}
          </div>
        </div>

        <div className="mt-auto p-8 border-t border-slate-800">
          <button className="flex items-center gap-3 text-slate-500 hover:text-white transition-colors w-full group">
            <LogOut size={20} className="group-hover:translate-x-1 transition-transform" />
            <span className="font-bold text-xs uppercase tracking-widest">{t.signOut}</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto">
        <header className="bg-white/80 backdrop-blur-md border-b border-slate-200 sticky top-0 z-30 px-8 py-4 flex items-center justify-between">
          <div className="flex items-center gap-6">
            <h2 className="text-xl font-black text-slate-900 tracking-tight uppercase">
              {activeTab === 'settings' ? t.settings : activeTab === 'dashboard' ? t.dashboard : t.inventory}
            </h2>
            <button 
              onClick={toggleLanguage}
              className="flex items-center gap-2 px-3 py-1.5 bg-slate-100 rounded-lg text-[10px] font-black uppercase tracking-widest text-slate-600 hover:bg-rose-50 hover:text-rose-700 transition-all border border-slate-200"
            >
              <Languages size={14} />
              {lang === 'en' ? 'Tiếng Việt' : 'English'}
            </button>
          </div>

          <div className="flex items-center gap-3">
            <button 
              onClick={generateInsights}
              disabled={isAnalyzing}
              className="hidden lg:flex items-center gap-2 px-4 py-2.5 bg-rose-50 text-rose-700 rounded-xl font-black text-[11px] uppercase tracking-widest hover:bg-rose-100 transition-all border border-rose-100"
            >
              {isAnalyzing ? <Loader2 className="animate-spin" size={16} /> : <Sparkles size={16} />}
              {t.aiInsights}
            </button>

            <div className="h-8 w-[1px] bg-slate-200 mx-2 hidden md:block"></div>

            <button 
              onClick={() => storageService.exportToCSV(devices)}
              className="p-2.5 bg-white text-slate-600 rounded-xl hover:bg-slate-100 transition-colors border border-slate-200 shadow-sm"
              title={t.backupCsv}
            >
              <Download size={20} />
            </button>

            <button 
              onClick={() => { setEditingDevice(null); setIsFormOpen(true); }}
              className="flex items-center gap-2 px-6 py-2.5 bg-rose-700 text-white rounded-xl font-black text-[11px] uppercase tracking-widest shadow-xl shadow-rose-900/20 hover:bg-rose-800 transition-all active:scale-95"
            >
              <Plus size={18} />
              {t.addDevice}
            </button>
          </div>
        </header>

        <div className="p-8 max-w-7xl mx-auto space-y-8">
          {aiInsights && (
            <div className="bg-rose-700 p-[1px] rounded-3xl overflow-hidden shadow-2xl animate-in slide-in-from-top-4 duration-500">
              <div className="bg-white/95 backdrop-blur-sm p-8 rounded-[23px] relative">
                <button onClick={() => setAiInsights(null)} className="absolute top-6 right-6 p-2 text-slate-400 hover:text-rose-600 transition-all">
                  <Plus className="rotate-45" size={24} />
                </button>
                <div className="flex gap-6">
                  <div className="w-16 h-16 bg-rose-50 rounded-2xl flex items-center justify-center text-rose-700 shrink-0">
                    <Sparkles size={32} />
                  </div>
                  <div>
                    <h3 className="font-black text-slate-900 text-xl mb-3 tracking-tight uppercase">{t.aiInsights}</h3>
                    <div className="text-slate-600 text-base leading-relaxed whitespace-pre-line font-medium">{aiInsights}</div>
                  </div>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'dashboard' && <Dashboard devices={devices} lang={lang} />}
          {activeTab === 'inventory' && (
            <DeviceTable 
              devices={devices} 
              onEdit={(d) => { setEditingDevice(d); setIsFormOpen(true); }} 
              onDelete={deleteDevice}
              onViewHistory={(d) => setHistoryDevice(d)}
              lang={lang}
            />
          )}

          {activeTab === 'settings' && (
            <div className="bg-white p-10 rounded-3xl border border-slate-200 shadow-sm max-w-2xl mx-auto space-y-8">
              <div className="flex items-center gap-4">
                <div className="p-4 bg-rose-50 rounded-2xl text-rose-700">
                  <Cloud size={32} />
                </div>
                <div>
                  <h3 className="text-xl font-black text-slate-900 uppercase tracking-tight">{t.cloudSync}</h3>
                  <p className="text-xs text-slate-500 mt-1">Connect with Google Sheets for cross-device data access.</p>
                </div>
              </div>

              <div className="space-y-4">
                <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1">Web App URL</label>
                <input 
                  type="text"
                  placeholder="https://script.google.com/..."
                  className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-rose-500/10 focus:border-rose-500 outline-none transition-all font-mono text-xs"
                  value={sheetUrl}
                  onChange={(e) => updateSheetUrl(e.target.value)}
                />
              </div>

              <div className="pt-6 border-t border-slate-100 flex justify-end">
                <button 
                  onClick={() => handleSync('pull')}
                  disabled={!sheetUrl || isSyncing}
                  className="px-8 py-3 bg-slate-900 text-white rounded-2xl font-black text-[10px] uppercase tracking-widest hover:bg-rose-700 transition-all flex items-center gap-2 disabled:opacity-50"
                >
                  {isSyncing ? <Loader2 size={16} className="animate-spin" /> : <RefreshCw size={16} />}
                  {t.syncNow}
                </button>
              </div>
            </div>
          )}
        </div>
      </main>

      {isFormOpen && <DeviceForm device={editingDevice} onSave={saveDevice} onClose={() => setIsFormOpen(false)} lang={lang} />}
      {historyDevice && <HistoryModal device={historyDevice} onClose={() => setHistoryDevice(null)} lang={lang} />}
    </div>
  );
};

const SidebarLink = ({ active, onClick, icon, label }: any) => (
  <button 
    onClick={onClick} 
    className={`flex items-center gap-4 w-full px-6 py-4 rounded-2xl transition-all duration-300 group ${
      active 
        ? 'bg-rose-700 text-white font-black shadow-lg shadow-rose-900/30' 
        : 'text-slate-500 hover:bg-slate-800 hover:text-slate-200'
    }`}
  >
    <div className={`${active ? 'text-white' : 'text-slate-600 group-hover:text-rose-500'} transition-colors`}>
      {icon}
    </div>
    <span className="text-[11px] uppercase font-black tracking-widest">{label}</span>
  </button>
);

export default App;

import React, { useMemo } from 'react';
import { PieChart, Pie, Cell, ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Legend } from 'recharts';
import { Device } from '../types';
import { translations } from '../translations';
import { Monitor, Smartphone, ShieldAlert, CheckCircle } from 'lucide-react';

interface Props {
  devices: Device[];
  lang: 'en' | 'vi';
}

const COLORS = ['#be123c', '#1e293b', '#475569', '#9f1239', '#fb7185'];

const Dashboard: React.FC<Props> = ({ devices, lang }) => {
  const t = translations[lang];

  const stats = useMemo(() => {
    const today = new Date();
    const threeMonthsFromNow = new Date();
    threeMonthsFromNow.setMonth(today.getMonth() + 3);

    const typeCounts: Record<string, number> = {};
    let assigned = 0;
    let expiring = 0;

    devices.forEach(d => {
      typeCounts[d.type] = (typeCounts[d.type] || 0) + 1;
      if (d.status === 'Assigned') assigned++;

      const expiry = new Date(d.warrantyExpiry);
      if (expiry > today && expiry < threeMonthsFromNow) expiring++;
    });

    const typeData = Object.entries(typeCounts).map(([name, value]) => ({ name, value }));

    return {
      total: devices.length,
      assigned,
      expiring,
      typeData
    };
  }, [devices]);

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard icon={<Monitor size={24} className="text-rose-600" />} title={t.totalAssets} value={stats.total} color="bg-rose-50" />
        <StatCard icon={<CheckCircle size={24} className="text-slate-800" />} title={t.assigned} value={stats.assigned} color="bg-slate-100" />
        <StatCard icon={<ShieldAlert size={24} className="text-rose-600" />} title={t.expiringSoon} value={stats.expiring} subtitle="Next 90 days" color="bg-rose-50" />
        <StatCard icon={<Smartphone size={24} className="text-slate-800" />} title={t.deviceTypes} value={stats.typeData.length} color="bg-slate-100" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-8 rounded-3xl border border-slate-200 h-[400px] shadow-sm">
          <h3 className="text-[10px] font-black text-slate-400 mb-6 uppercase tracking-[0.2em]">{t.assetDist}</h3>
          <ResponsiveContainer width="100%" height="90%">
            <PieChart>
              <Pie data={stats.typeData} cx="50%" cy="50%" innerRadius={70} outerRadius={90} paddingAngle={8} dataKey="value">
                {stats.typeData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Pie>
              <Tooltip />
              <Legend verticalAlign="bottom" height={36}/>
            </PieChart>
          </ResponsiveContainer>
        </div>

        <div className="bg-white p-8 rounded-3xl border border-slate-200 h-[400px] shadow-sm">
          <h3 className="text-[10px] font-black text-slate-400 mb-6 uppercase tracking-[0.2em]">{t.countByType}</h3>
          <ResponsiveContainer width="100%" height="90%">
            <BarChart data={stats.typeData}>
              <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fontWeight: 700, fill: '#64748b'}} />
              <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} />
              <Tooltip cursor={{fill: '#f8fafc'}} />
              <Bar dataKey="value" fill="#be123c" radius={[8, 8, 0, 0]} barSize={40} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

const StatCard = ({ icon, title, value, color, subtitle }: any) => (
