import React, { useMemo } from 'react';
import { PieChart, Pie, Cell, ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, Legend } from 'recharts';
import { Device } from '../types';
import { translations } from '../translations';
import { Monitor, Smartphone, ShieldAlert, CheckCircle } from 'lucide-react';

interface Props {
  devices: Device[];
  lang: 'en' | 'vi';
}

const COLORS = ['#4f46e5', '#1e293b', '#6366f1', '#94a3b8', '#818cf8'];

const Dashboard: React.FC<Props> = ({ devices, lang }) => {
  const t = translations[lang];

  const stats = useMemo(() => {
    const today = new Date();
    const threeMonthsFromNow = new Date();
    threeMonthsFromNow.setMonth(today.getMonth() + 3);

    const typeCounts: Record<string, number> = {};
    let assigned = 0;
    let expiring = 0;

    devices.forEach(d => {
      typeCounts[d.type] = (typeCounts[d.type] || 0) + 1;
      if (d.status === 'Assigned') assigned++;

      const expiry = new Date(d.warrantyExpiry);
      if (expiry > today && expiry < threeMonthsFromNow) expiring++;
    });

    const typeData = Object.entries(typeCounts).map(([name, value]) => ({ name, value }));

    return {
      total: devices.length,
      assigned,
      expiring,
      typeData
    };
  }, [devices]);

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard icon={<Monitor size={24} className="text-indigo-600" />} title={t.totalAssets} value={stats.total} color="bg-white" />
        <StatCard icon={<CheckCircle size={24} className="text-green-600" />} title={t.assigned} value={stats.assigned} color="bg-white" />
        <StatCard icon={<ShieldAlert size={24} className="text-amber-600" />} title={t.expiringSoon} value={stats.expiring} subtitle="Next 90 days" color="bg-white" />
        <StatCard icon={<Smartphone size={24} className="text-slate-600" />} title={t.deviceTypes} value={stats.typeData.length} color="bg-white" />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <div className="bg-white p-8 rounded-3xl border border-slate-200 h-[400px] shadow-sm">
          <h3 className="text-xs font-bold text-slate-400 mb-6 uppercase tracking-wider">{t.assetDist}</h3>
          <ResponsiveContainer width="100%" height="90%">
            <PieChart>
              <Pie data={stats.typeData} cx="50%" cy="50%" innerRadius={70} outerRadius={90} paddingAngle={8} dataKey="value">
                {stats.typeData.map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Pie>
              <Tooltip />
              <Legend verticalAlign="bottom" height={36}/>
            </PieChart>
          </ResponsiveContainer>
        </div>

        <div className="bg-white p-8 rounded-3xl border border-slate-200 h-[400px] shadow-sm">
          <h3 className="text-xs font-bold text-slate-400 mb-6 uppercase tracking-wider">{t.countByType}</h3>
          <ResponsiveContainer width="100%" height="90%">
            <BarChart data={stats.typeData}>
              <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#64748b'}} />
              <YAxis axisLine={false} tickLine={false} tick={{fontSize: 10, fill: '#94a3b8'}} />
              <Tooltip cursor={{fill: '#f8fafc'}} />
              <Bar dataKey="value" fill="#4f46e5" radius={[8, 8, 0, 0]} barSize={40} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>
    </div>
  );
};

const StatCard = ({ icon, title, value, color, subtitle }: any) => (
  <div className={`${color} p-8 rounded-3xl border border-slate-200 shadow-sm transition-transform hover:scale-[1.02]`}>
    <div className="flex items-center justify-between mb-4">
      <div className="p-3 bg-slate-50 rounded-2xl">{icon}</div>
      <span className="text-3xl font-bold text-slate-900">{value}</span>
    </div>
    <div className="text-xs font-bold text-slate-500 uppercase tracking-wider">{title}</div>
    {subtitle && <div className="text-[10px] text-slate-400 mt-1 uppercase font-medium">{subtitle}</div>}
  </div>
);

export default Dashboard;

import React, { useState } from 'react';
import { Device, DeviceType } from '../types';
import { translations } from '../translations';
import { Search, Edit2, Trash2, Filter, History } from 'lucide-react';

interface Props {
  devices: Device[];
  onEdit: (device: Device) => void;
  onDelete: (id: string) => void;
  onViewHistory: (device: Device) => void;
  lang: 'en' | 'vi';
}

const DeviceTable: React.FC<Props> = ({ devices, onEdit, onDelete, onViewHistory, lang }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [typeFilter, setTypeFilter] = useState<string>('All');
  const t = translations[lang];

  const filteredDevices = devices.filter(d => {
    const matchesSearch = 
      d.manufacturer.toLowerCase().includes(searchTerm.toLowerCase()) ||
      d.model.toLowerCase().includes(searchTerm.toLowerCase()) ||
      d.serialNumber.toLowerCase().includes(searchTerm.toLowerCase()) ||
      d.assignedTo.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesType = typeFilter === 'All' || d.type === typeFilter;

    return matchesSearch && matchesType;
  });

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'Available': return 'bg-green-100 text-green-700';
      case 'Assigned': return 'bg-blue-100 text-blue-700';
      case 'Maintenance': return 'bg-amber-100 text-amber-700';
      case 'Retired': return 'bg-slate-200 text-slate-700';
      default: return 'bg-slate-100 text-slate-700';
    }
  };

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
      <div className="p-6 border-b border-slate-100 flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div className="relative flex-1 max-w-md">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            type="text"
            placeholder={t.searchPlaceholder}
            className="w-full pl-12 pr-6 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 outline-none text-sm transition-all"
            value={searchTerm}
            onChange={e => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="flex items-center gap-4">
          <div className="flex items-center gap-2">
            <Filter size={16} className="text-slate-400" />
            <select 
              className="bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold uppercase tracking-widest focus:ring-4 focus:ring-indigo-500/10 outline-none cursor-pointer"
              value={typeFilter}
              onChange={e => setTypeFilter(e.target.value)}
            >
              <option value="All">{t.allTypes}</option>
              {Object.values(DeviceType).map(v => <option key={v} value={v}>{v}</option>)}
            </select>
          </div>
        </div>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-slate-50/50">
              <th className="px-8 py-5 text-xs font-bold text-slate-400 uppercase tracking-wider">{t.asset}</th>
              <th className="px-8 py-5 text-xs font-bold text-slate-400 uppercase tracking-wider">{t.serial}</th>
              <th className="px-8 py-5 text-xs font-bold text-slate-400 uppercase tracking-wider">{t.dates}</th>
              <th className="px-8 py-5 text-xs font-bold text-slate-400 uppercase tracking-wider">{t.assignee}</th>
              <th className="px-8 py-5 text-xs font-bold text-slate-400 uppercase tracking-wider">{t.status}</th>
              <th className="px-8 py-5 text-xs font-bold text-slate-400 uppercase tracking-wider text-right">{t.actions}</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filteredDevices.map(device => (
              <tr key={device.id} className="hover:bg-slate-50/50 transition-colors group">
                <td className="px-8 py-5">
                  <div className="flex flex-col">
                    <span className="font-semibold text-slate-900">{device.manufacturer} {device.model}</span>
                    <span className="text-[10px] font-bold text-indigo-600 uppercase tracking-wider mt-0.5">{device.type}</span>
                  </div>
                </td>
                <td className="px-8 py-5">
                  <code className="text-xs font-mono bg-slate-100 text-slate-700 px-2.5 py-1.5 rounded-lg">{device.serialNumber}</code>
                </td>
                <td className="px-8 py-5">
                  <div className="space-y-1">
                    <div className="flex items-center gap-2">
                      <span className="text-[10px] font-bold text-slate-400 uppercase w-16">{t.bought}</span>
                      <span className="text-xs font-medium text-slate-700">{device.purchaseDate}</span>
                    </div>
                    <div className="flex items-center gap-2">
                      <span className="text-[10px] font-bold text-slate-400 uppercase w-16">{t.expiry}</span>
                      <span className="text-xs font-medium text-indigo-700">{device.warrantyExpiry}</span>
                    </div>
                  </div>
                </td>
                <td className="px-8 py-5">
                  {device.assignedTo ? (
                    <div className="flex flex-col">
                      <span className="text-sm font-semibold text-slate-900">{device.assignedTo}</span>
                      <span className="text-[10px] text-slate-400 uppercase font-medium mt-0.5">{device.handoverDate || 'N/A'}</span>
                    </div>
                  ) : (
                    <span className="text-xs text-slate-400 italic">{t.unassigned}</span>
                  )}
                </td>
                <td className="px-8 py-5">
                  <span className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider ${getStatusColor(device.status)}`}>
                    {device.status}
