    if (window.confirm('Delete this device permanently?')) {
      const updated = devices.filter(d => d.id !== id);
      setDevices(updated);
      storageService.saveDevicesLocal(updated);
      if (sheetUrl) handleSync('push', updated);
    }
  };

  const updateSheetUrl = (url: string) => {
    setSheetUrl(url);
    storageService.saveSettings({ sheetUrl: url });
  };

  const generateInsights = async () => {
    setIsAnalyzing(true);
    try {
      const insight = await geminiService.analyzeInventory(devices);
      setAiInsights(insight);
    } catch (error) {
      setAiInsights("AI Analysis failed. Please try again later.");
    } finally {
      setIsAnalyzing(false);
    }
  };

