              title={t.backupCsv}
            >
              <Download size={20} />
            </button>

            <button 
              onClick={() => { setEditingDevice(null); setIsFormOpen(true); }}
              className="flex items-center gap-2 px-6 py-2.5 bg-indigo-600 text-white rounded-xl font-bold text-sm shadow-xl shadow-indigo-500/20 hover:bg-indigo-700 transition-all active:scale-95"
            >
              <Plus size={18} />
              {t.addDevice}
            </button>
          </div>
        </header>

        <div className="p-8 max-w-7xl mx-auto space-y-8">
          {aiInsights && (
            <div className="bg-gradient-to-br from-indigo-600 to-blue-700 p-[1px] rounded-3xl overflow-hidden shadow-2xl shadow-indigo-200 animate-in slide-in-from-top-4 duration-500">
              <div className="bg-white/95 backdrop-blur-sm p-8 rounded-[23px] relative">
                <button onClick={() => setAiInsights(null)} className="absolute top-6 right-6 p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-full transition-all">
                  <Plus className="rotate-45" size={24} />
                </button>
                <div className="flex gap-6">
                  <div className="w-16 h-16 bg-indigo-100 rounded-2xl flex items-center justify-center text-indigo-600 shrink-0">
                    <Sparkles size={32} />
                  </div>
                  <div>
                    <h3 className="font-black text-slate-900 text-xl mb-3 tracking-tight">{t.aiInsights}</h3>
                    <div className="text-slate-600 text-base leading-relaxed whitespace-pre-line font-medium">{aiInsights}</div>
                  </div>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'dashboard' && <Dashboard devices={devices} lang={lang} />}
          {activeTab === 'inventory' && (
            <DeviceTable 
              devices={devices} 
              onEdit={(d) => { setEditingDevice(d); setIsFormOpen(true); }} 
              onDelete={deleteDevice}
              onViewHistory={(d) => setHistoryDevice(d)}
              lang={lang}
            />
          )}

          {activeTab === 'settings' && (
            <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm max-w-2xl mx-auto space-y-8">
              <div className="flex items-center gap-4">
                <div className="p-4 bg-indigo-50 rounded-2xl text-indigo-600">
                  <Cloud size={32} />
                </div>
                <div>
                  <h3 className="text-xl font-black text-slate-800">{t.cloudSync}</h3>
                  <p className="text-sm text-slate-500">Sync your device data across any device using Google Sheets.</p>
                </div>
              </div>

              <div className="space-y-4">
                <label className="block text-sm font-bold text-slate-700">Google Apps Script Web App URL</label>
                <input 
                  type="text"
                  placeholder="https://script.google.com/macros/s/.../exec"
                  className="w-full px-5 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-4 focus:ring-indigo-500/10 outline-none transition-all font-mono text-xs"
                  value={sheetUrl}
                  onChange={(e) => updateSheetUrl(e.target.value)}
                />
              </div>

              <div className="pt-6 border-t border-slate-100 flex justify-end gap-3">
                <button 
                  onClick={() => handleSync('pull')}
                  disabled={!sheetUrl || isSyncing}
                  className="px-6 py-2.5 bg-white border border-slate-200 rounded-xl font-bold text-sm text-slate-600 hover:bg-slate-50 transition-all flex items-center gap-2 disabled:opacity-50"
                >
                  {isSyncing ? <Loader2 size={16} className="animate-spin" /> : <RefreshCw size={16} />}
                  {t.syncNow}
                </button>
              </div>
            </div>
          )}
        </div>
      </main>

      {isFormOpen && <DeviceForm device={editingDevice} onSave={saveDevice} onClose={() => setIsFormOpen(false)} lang={lang} />}
      {historyDevice && <HistoryModal device={historyDevice} onClose={() => setHistoryDevice(null)} lang={lang} />}
    </div>
  );
};

const SidebarLink = ({ active, onClick, icon, label }: any) => (
  <button 
