              <img 
                src="https://d2nyjryheal9w7.cloudfront.net/610a5b0dbd9b2500172ecee5/%E7%A8%B2%E7%95%91%E7%94%A3%E6%A5%AD%E3%83%AD%E3%82%B4%20(1).png" 
                alt="Logo" 
                className="w-full h-full object-contain p-1"
                onError={(e) => {
                  e.currentTarget.style.display = 'none';
                  e.currentTarget.parentElement!.innerHTML = '<div class="text-indigo-600 font-black">IK</div>';
                }}
              />
            </div>
            <div>
