                  onClick={() => handleSync('pull')}
                  disabled={isSyncing}
                  className="w-full mt-2 py-1.5 bg-slate-700 hover:bg-slate-600 rounded-lg text-[10px] font-bold uppercase tracking-wider transition-colors"
                >
                  {t.syncNow}
                </button>
              </div>
            ) : (
              <p className="text-[10px] text-slate-500 italic">Chưa cấu hình Google Sheet.</p>
            )}
          </div>
        </div>

        <div className="mt-auto p-8 border-t border-slate-800">
          <button className="flex items-center gap-3 text-slate-400 hover:text-white transition-colors w-full group">
            <LogOut size={20} className="group-hover:translate-x-1 transition-transform" />
            <span className="font-medium text-sm">{t.signOut}</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto">
        <header className="bg-white/80 backdrop-blur-md border-b border-slate-200 sticky top-0 z-30 px-8 py-5 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <h2 className="text-2xl font-black text-slate-800 tracking-tight capitalize">
              {activeTab === 'settings' ? t.settings : activeTab === 'dashboard' ? t.dashboard : t.inventory}
            </h2>
            <button 
              onClick={toggleLanguage}
              className="flex items-center gap-2 px-3 py-1.5 bg-slate-100 rounded-lg text-[10px] font-bold uppercase text-slate-600 hover:bg-indigo-50 hover:text-indigo-700 transition-all border border-slate-200"
            >
              <Languages size={14} />
              {lang === 'en' ? 'Tiếng Việt' : 'English'}
            </button>
          </div>

          <div className="flex items-center gap-3">
            <button 
              onClick={generateInsights}
              disabled={isAnalyzing}
              className="hidden lg:flex items-center gap-2 px-4 py-2.5 bg-indigo-50 text-indigo-700 rounded-xl font-bold text-sm hover:bg-indigo-100 transition-all border border-indigo-100"
            >
              {isAnalyzing ? <Loader2 className="animate-spin" size={16} /> : <Sparkles size={16} />}
              {t.aiInsights}
            </button>

            <div className="h-8 w-[1px] bg-slate-200 mx-2 hidden md:block"></div>

            <div className="flex items-center gap-2">
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleImportCSV} 
                accept=".csv" 
                className="hidden" 
              />
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="p-2.5 bg-slate-50 text-slate-600 rounded-xl hover:bg-slate-200 transition-colors border border-slate-200"
                title={t.importCsv}
              >
                <Upload size={20} />
              </button>

              <button 
                onClick={() => storageService.exportToCSV(devices)}
                className="p-2.5 bg-slate-50 text-slate-600 rounded-xl hover:bg-slate-200 transition-colors border border-slate-200"
                title={t.backupCsv}
              >
                <Download size={20} />
              </button>
            </div>

            <button 
              onClick={() => { setEditingDevice(null); setIsFormOpen(true); }}
              className="flex items-center gap-2 px-6 py-2.5 bg-indigo-600 text-white rounded-xl font-bold text-sm shadow-xl shadow-indigo-500/20 hover:bg-indigo-700 transition-all active:scale-95"
            >
              <Plus size={18} />
              {t.addDevice}
            </button>
          </div>
        </header>

        <div className="p-8 max-w-7xl mx-auto space-y-8">
          {aiInsights && (
            <div className="bg-gradient-to-br from-indigo-600 to-blue-700 p-[1px] rounded-3xl overflow-hidden shadow-2xl shadow-indigo-200 animate-in slide-in-from-top-4 duration-500">
              <div className="bg-white/95 backdrop-blur-sm p-8 rounded-[23px] relative">
                <button onClick={() => setAiInsights(null)} className="absolute top-6 right-6 p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-full transition-all">
                  <Plus className="rotate-45" size={24} />
                </button>
                <div className="flex gap-6">
                  <div className="w-16 h-16 bg-indigo-100 rounded-2xl flex items-center justify-center text-indigo-600 shrink-0">
                    <Sparkles size={32} />
                  </div>
                  <div>
                    <h3 className="font-black text-slate-900 text-xl mb-3 tracking-tight">{t.aiInsights}</h3>
                    <div className="text-slate-600 text-base leading-relaxed whitespace-pre-line font-medium">{aiInsights}</div>
                  </div>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'dashboard' && <Dashboard devices={devices} lang={lang} />}
          {activeTab === 'inventory' && (
            <DeviceTable 
              devices={devices} 
              onEdit={(d) => { setEditingDevice(d); setIsFormOpen(true); }} 
              onDelete={deleteDevice}
              onViewHistory={(d) => setHistoryDevice(d)}
              lang={lang}
            />
          )}

          {activeTab === 'settings' && (
            <div className="max-w-2xl mx-auto space-y-8">
              {/* Google Sheets Sync */}
              <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm space-y-8">
                <div className="flex items-center gap-4">
                  <div className="p-4 bg-indigo-50 rounded-2xl text-indigo-600">
                    <Cloud size={32} />
                  </div>
                  <div>
                    <h3 className="text-xl font-black text-slate-800">{t.cloudSync}</h3>
                    <p className="text-sm text-slate-500">Đồng bộ dữ liệu của bạn thông qua Google Sheets để lưu trữ lâu dài.</p>
                  </div>
                </div>

                <div className="space-y-4">
                  <label className="block text-sm font-bold text-slate-700">Google Apps Script Web App URL</label>
                  <input 
                    type="text"
                    placeholder="https://script.google.com/macros/s/.../exec"
                    className="w-full px-5 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-4 focus:ring-indigo-500/10 outline-none transition-all font-mono text-xs"
                    value={sheetUrl}
                    onChange={(e) => updateSheetUrl(e.target.value)}
                  />
                </div>

                <div className="pt-6 border-t border-slate-100 flex justify-end gap-3">
                  <button 
                    onClick={() => handleSync('pull')}
                    disabled={!sheetUrl || isSyncing}
                    className="px-6 py-2.5 bg-white border border-slate-200 rounded-xl font-bold text-sm text-slate-600 hover:bg-slate-50 transition-all flex items-center gap-2 disabled:opacity-50"
                  >
                    {isSyncing ? <Loader2 size={16} className="animate-spin" /> : <RefreshCw size={16} />}
                    {t.syncNow}
                  </button>
                </div>
              </div>

              {/* Netlify Link Sharing */}
              <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm space-y-8">
                <div className="flex items-center gap-4">
                  <div className="p-4 bg-green-50 rounded-2xl text-green-600">
                    <Share2 size={32} />
                  </div>
                  <div>
                    <h3 className="text-xl font-black text-slate-800">{t.shareApp}</h3>
                    <p className="text-sm text-slate-500">{t.shareDesc}</p>
                  </div>
                </div>

                <div className="flex items-center gap-3 p-4 bg-slate-50 border border-slate-200 rounded-2xl">
                  <div className="flex-1 truncate font-mono text-xs text-slate-600">
                    {window.location.href}
                  </div>
                  <button 
                    onClick={copyToClipboard}
                    className={`flex items-center gap-2 px-4 py-2 rounded-xl font-bold text-xs transition-all ${
                      showCopySuccess 
                        ? 'bg-green-600 text-white' 
                        : 'bg-indigo-600 text-white hover:bg-indigo-700'
                    }`}
                  >
                    {showCopySuccess ? <Check size={14} /> : <Copy size={14} />}
                    {showCopySuccess ? t.linkCopied : t.copyLink}
                  </button>
                </div>
              </div>

              {/* Maintenance Guide */}
              <div className="bg-slate-900 text-white p-8 rounded-3xl shadow-xl space-y-8 border border-slate-800">
                <div className="flex items-center gap-4">
                  <div className="p-4 bg-slate-800 rounded-2xl text-indigo-400">
                    <Code2 size={32} />
                  </div>
                  <div>
                    <h3 className="text-xl font-black">{t.adminGuide}</h3>
                    <p className="text-sm text-slate-400">{t.howToSave}</p>
                  </div>
                </div>

                <div className="space-y-4">
                  <div className="flex items-start gap-4 p-4 bg-slate-800/50 rounded-2xl border border-slate-700">
                    <Github className="shrink-0 mt-1 text-slate-400" size={20} />
                    <p className="text-sm font-medium leading-relaxed">{t.githubGuide}</p>
                  </div>
                  <div className="flex items-start gap-4 p-4 bg-slate-800/50 rounded-2xl border border-slate-700">
                    <RefreshCw className="shrink-0 mt-1 text-indigo-400" size={20} />
                    <p className="text-sm font-medium leading-relaxed">{t.netlifyAuto}</p>
                  </div>
                  <div className="flex items-start gap-4 p-4 bg-slate-800/50 rounded-2xl border border-slate-700">
                    <Sparkles className="shrink-0 mt-1 text-amber-400" size={20} />
                    <p className="text-sm font-medium leading-relaxed">{t.idxGuide}</p>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>

      {isFormOpen && <DeviceForm device={editingDevice} onSave={saveDevice} onClose={() => setIsFormOpen(false)} lang={lang} />}
      {historyDevice && <HistoryModal device={historyDevice} onClose={() => setHistoryDevice(null)} lang={lang} />}
    </div>
  );
};

const SidebarLink = ({ active, onClick, icon, label }: any) => (
  <button 
    onClick={onClick} 
    className={`flex items-center gap-4 w-full px-5 py-3.5 rounded-2xl transition-all duration-300 group ${
      active 
        ? 'bg-indigo-600 text-white font-bold shadow-lg shadow-indigo-600/20' 
        : 'text-slate-400 hover:bg-slate-800 hover:text-slate-200'
    }`}
  >
    <div className={`${active ? 'text-white' : 'text-slate-500 group-hover:text-indigo-400'} transition-colors`}>
      {icon}
    </div>
    <span className="text-sm tracking-wide">{label}</span>
  </button>
);

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Device, DeviceType, HistoryEntry } from './types';
import { storageService } from './services/storageService';
import { geminiService } from './services/geminiService';
import { translations } from './translations';
import Dashboard from './components/Dashboard';
import DeviceTable from './components/DeviceTable';
import DeviceForm from './components/DeviceForm';
import HistoryModal from './components/HistoryModal';
import { 
  Plus, Download, Upload, Sparkles, LayoutDashboard, 
  Database, LogOut, Loader2, CheckCircle2, Cloud, 
  Settings as SettingsIcon, AlertCircle, RefreshCw, Languages,
  Share2, Copy, Check, Github, Code2
} from 'lucide-react';

const App: React.FC = () => {
  const [lang, setLang] = useState<'en' | 'vi'>('vi');
  const [devices, setDevices] = useState<Device[]>([]);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'inventory' | 'settings'>('dashboard');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingDevice, setEditingDevice] = useState<Device | null>(null);
  const [historyDevice, setHistoryDevice] = useState<Device | null>(null);
  const [aiInsights, setAiInsights] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [sheetUrl, setSheetUrl] = useState<string>(storageService.getSettings().sheetUrl);
  const [syncStatus, setSyncStatus] = useState<'idle' | 'success' | 'error'>('idle');
  const [showCopySuccess, setShowCopySuccess] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const t = translations[lang];

  // Ngày cập nhật để kiểm tra Deploy
  const lastUpdated = "2024-05-24 15:30 (Import Fix)";

  useEffect(() => {
    const loadInitialData = async () => {
      const localData = storageService.getDevicesLocal();
      if (localData.length > 0) setDevices(localData);
      if (sheetUrl) {
        handleSync('pull');
      }
    };
    loadInitialData();
  }, []);

  const toggleLanguage = () => setLang(prev => prev === 'en' ? 'vi' : 'en');

  const handleSync = async (direction: 'pull' | 'push', updatedDevices?: Device[]) => {
    if (!sheetUrl) return;
    setIsSyncing(true);
    setSyncStatus('idle');
    try {
      const targetData = updatedDevices || devices;
      const result = await storageService.syncWithGoogleSheet(sheetUrl, direction === 'push' ? targetData : undefined);
      if (direction === 'pull' && result) {
        setDevices(result);
        storageService.saveDevicesLocal(result);
      }
      setSyncStatus('success');
    } catch (error) {
      setSyncStatus('error');
    } finally {
      setIsSyncing(false);
    }
  };

  const handleImportCSV = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target?.result as string;
      try {
        const importedDevices = storageService.parseCSV(text);

        // Filter out duplicates based on Serial Number
        const currentSerials = new Set(devices.map(d => d.serialNumber.toLowerCase()));
        const newDevices = importedDevices.filter(d => !currentSerials.has(d.serialNumber.toLowerCase()));

        if (newDevices.length === 0) {
          alert("Tất cả thiết bị trong file đã tồn tại hoặc file không hợp lệ.");
          return;
        }

        const updatedDevices = [...devices, ...newDevices];
        setDevices(updatedDevices);
        storageService.saveDevicesLocal(updatedDevices);

        const msg = t.importSuccess.replace('{count}', newDevices.length.toString());
        alert(msg);

        if (sheetUrl) {
          handleSync('push', updatedDevices);
        }
      } catch (err) {
        alert(t.importError);
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(window.location.href);
    setShowCopySuccess(true);
    setTimeout(() => setShowCopySuccess(false), 2000);
  };

  const saveDevice = async (newDeviceData: Device) => {
    const isDuplicateSerial = devices.some(d => 
      d.serialNumber.toLowerCase() === newDeviceData.serialNumber.toLowerCase() && 
      d.id !== newDeviceData.id
    );

    if (isDuplicateSerial) {
      alert(`Error: Serial Number "${newDeviceData.serialNumber}" already exists!`);
      return;
    }

    let updatedDevices: Device[];
    const now = new Date().toISOString().split('T')[0];

    if (editingDevice) {
      const isAssigneeChanged = editingDevice.assignedTo !== newDeviceData.assignedTo;
      const isStatusChanged = editingDevice.status !== newDeviceData.status;
      const newHistory: HistoryEntry[] = [...(newDeviceData.history || [])];

      if (isAssigneeChanged || isStatusChanged) {
        newHistory.push({
          id: Math.random().toString(36).substr(2, 9),
          assignee: newDeviceData.assignedTo || t.unassigned,
          date: newDeviceData.handoverDate || now,
          notes: isAssigneeChanged 
            ? `Bàn giao: Từ "${editingDevice.assignedTo || 'Kho'}" sang "${newDeviceData.assignedTo || 'Người mới'}"`
            : `Cập nhật trạng thái: ${newDeviceData.status}`
        });
      }

      const updatedDevice = { ...newDeviceData, history: newHistory };
      updatedDevices = devices.map(d => d.id === newDeviceData.id ? updatedDevice : d);
    } else {
      const initialHistory: HistoryEntry[] = [{
        id: Math.random().toString(36).substr(2, 9),
        assignee: newDeviceData.assignedTo || 'IT Stock',
        date: newDeviceData.purchaseDate || now,
        notes: 'Đăng ký thiết bị mới'
      }];
      updatedDevices = [...devices, { ...newDeviceData, history: initialHistory }];
    }

    setDevices(updatedDevices);
    storageService.saveDevicesLocal(updatedDevices);
    setIsFormOpen(false);
    setEditingDevice(null);

    if (sheetUrl) {
      handleSync('push', updatedDevices);
    }
  };

  const deleteDevice = (id: string) => {
    if (window.confirm('Bạn có chắc chắn muốn xóa thiết bị này?')) {
      const updated = devices.filter(d => d.id !== id);
      setDevices(updated);
      storageService.saveDevicesLocal(updated);
      if (sheetUrl) handleSync('push', updated);
    }
  };

  const updateSheetUrl = (url: string) => {
    setSheetUrl(url);
    storageService.saveSettings({ sheetUrl: url });
  };

  const generateInsights = async () => {
    setIsAnalyzing(true);
    try {
      const insight = await geminiService.analyzeInventory(devices);
      setAiInsights(insight);
    } catch (error) {
      setAiInsights("Phân tích AI thất bại. Vui lòng thử lại sau.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="flex min-h-screen bg-slate-50 text-slate-900">
      {/* Sidebar */}
      <aside className="hidden md:flex w-72 flex-col bg-slate-900 text-slate-300 sticky top-0 h-screen">
        <div className="p-8">
          <div className="flex items-center gap-3 mb-10">
            <div className="w-12 h-12 bg-white rounded-xl flex items-center justify-center overflow-hidden shadow-xl shadow-black/20 border border-slate-700">
              <img 
                src="https://d2nyjryheal9w7.cloudfront.net/610a5b0dbd9b2500172ecee5/%E7%A8%B2%E7%95%91%E7%94%A3%E6%A5%AD%E3%83%AD%E3%82%B4%20(1).png" 
                alt="Logo" 
                className="w-full h-full object-contain p-1"
                onError={(e) => {
                  e.currentTarget.style.display = 'none';
                  e.currentTarget.parentElement!.innerHTML = '<div class="text-indigo-600 font-black">IK</div>';
                }}
              />
            </div>
            <div>
              <h1 className="font-bold text-white text-lg leading-tight tracking-tight">{t.appName}</h1>
              <p className="text-[10px] text-indigo-400 font-bold uppercase tracking-widest">{t.subName}</p>
            </div>
          </div>

          <nav className="space-y-2">
            <SidebarLink active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon={<LayoutDashboard size={20} />} label={t.dashboard} />
            <SidebarLink active={activeTab === 'inventory'} onClick={() => setActiveTab('inventory')} icon={<Database size={20} />} label={t.inventory} />
            <SidebarLink active={activeTab === 'settings'} onClick={() => setActiveTab('settings')} icon={<SettingsIcon size={20} />} label={t.settings} />
          </nav>

          <div className="mt-10 p-4 bg-slate-800/50 rounded-2xl border border-slate-700/50">
            <div className="flex items-center justify-between mb-3">
              <div className="flex items-center gap-2 text-xs font-bold text-slate-400 uppercase">
                <Cloud size={14} className={sheetUrl ? "text-green-400" : "text-amber-400"} />
                {t.cloudSync}
              </div>
              {isSyncing && <RefreshCw size={12} className="animate-spin text-indigo-400" />}
            </div>
            {sheetUrl ? (
              <div className="space-y-2">
                <div className={`flex items-center gap-2 text-xs font-medium ${syncStatus === 'error' ? 'text-red-400' : 'text-green-400'}`}>
                  {syncStatus === 'error' ? <AlertCircle size={14}/> : <CheckCircle2 size={14} />}
                  {syncStatus === 'error' ? t.syncFailed : t.connected}
                </div>
                <button 
                  onClick={() => handleSync('pull')}
                  disabled={isSyncing}
                  className="w-full mt-2 py-1.5 bg-slate-700 hover:bg-slate-600 rounded-lg text-[10px] font-bold uppercase tracking-wider transition-colors"
                >
                  {t.syncNow}
                </button>
              </div>
            ) : (
              <p className="text-[10px] text-slate-500 italic">Chưa cấu hình Google Sheet.</p>
            )}
          </div>
        </div>

        <div className="mt-auto p-8 border-t border-slate-800 space-y-4">
          <div className="text-[10px] text-slate-500 font-mono text-center">
             Build: {lastUpdated}
          </div>
          <button className="flex items-center gap-3 text-slate-400 hover:text-white transition-colors w-full group">
            <LogOut size={20} className="group-hover:translate-x-1 transition-transform" />
            <span className="font-medium text-sm">{t.signOut}</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 overflow-y-auto">
        <header className="bg-white/80 backdrop-blur-md border-b border-slate-200 sticky top-0 z-30 px-8 py-5 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <h2 className="text-2xl font-black text-slate-800 tracking-tight capitalize">
              {activeTab === 'settings' ? t.settings : activeTab === 'dashboard' ? t.dashboard : t.inventory}
            </h2>
            <button 
              onClick={toggleLanguage}
              className="flex items-center gap-2 px-3 py-1.5 bg-slate-100 rounded-lg text-[10px] font-bold uppercase text-slate-600 hover:bg-indigo-50 hover:text-indigo-700 transition-all border border-slate-200"
            >
              <Languages size={14} />
              {lang === 'en' ? 'Tiếng Việt' : 'English'}
            </button>
          </div>

          <div className="flex items-center gap-3">
            <button 
              onClick={generateInsights}
              disabled={isAnalyzing}
              className="hidden lg:flex items-center gap-2 px-4 py-2.5 bg-indigo-50 text-indigo-700 rounded-xl font-bold text-sm hover:bg-indigo-100 transition-all border border-indigo-100"
            >
              {isAnalyzing ? <Loader2 className="animate-spin" size={16} /> : <Sparkles size={16} />}
              {t.aiInsights}
            </button>

            <div className="h-8 w-[1px] bg-slate-200 mx-2 hidden md:block"></div>

            <div className="flex items-center gap-2">
              <input 
                type="file" 
                ref={fileInputRef} 
                onChange={handleImportCSV} 
                accept=".csv" 
                className="hidden" 
              />
              <button 
                onClick={() => fileInputRef.current?.click()}
                className="p-2.5 bg-slate-50 text-slate-600 rounded-xl hover:bg-slate-200 transition-colors border border-slate-200"
                title={t.importCsv}
              >
                <Upload size={20} />
              </button>

              <button 
                onClick={() => storageService.exportToCSV(devices)}
                className="p-2.5 bg-slate-50 text-slate-600 rounded-xl hover:bg-slate-200 transition-colors border border-slate-200"
                title={t.backupCsv}
              >
                <Download size={20} />
              </button>
            </div>

            <button 
              onClick={() => { setEditingDevice(null); setIsFormOpen(true); }}
              className="flex items-center gap-2 px-6 py-2.5 bg-indigo-600 text-white rounded-xl font-bold text-sm shadow-xl shadow-indigo-500/20 hover:bg-indigo-700 transition-all active:scale-95"
            >
              <Plus size={18} />
              {t.addDevice}
            </button>
          </div>
        </header>

        <div className="p-8 max-w-7xl mx-auto space-y-8">
          {aiInsights && (
            <div className="bg-gradient-to-br from-indigo-600 to-blue-700 p-[1px] rounded-3xl overflow-hidden shadow-2xl shadow-indigo-200 animate-in slide-in-from-top-4 duration-500">
              <div className="bg-white/95 backdrop-blur-sm p-8 rounded-[23px] relative">
                <button onClick={() => setAiInsights(null)} className="absolute top-6 right-6 p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-full transition-all">
                  <Plus className="rotate-45" size={24} />
                </button>
                <div className="flex gap-6">
                  <div className="w-16 h-16 bg-indigo-100 rounded-2xl flex items-center justify-center text-indigo-600 shrink-0">
                    <Sparkles size={32} />
