import React, { useState, useEffect, useRef } from 'react';
import { Device, DeviceType, HistoryEntry } from './types';
import { storageService } from './services/storageService';
import { geminiService } from './services/geminiService';
import { translations } from './translations';
import Dashboard from './components/Dashboard';
import DeviceTable from './components/DeviceTable';
import DeviceForm from './components/DeviceForm';
import HistoryModal from './components/HistoryModal';
import { 
  Plus, Download, Upload, Sparkles, LayoutDashboard, 
  Database, LogOut, Loader2, CheckCircle2, Cloud, 
  Settings as SettingsIcon, AlertCircle, RefreshCw, Languages,
  Share2, Copy, Check, Github, Code2
} from 'lucide-react';

const App: React.FC = () => {
  const [lang, setLang] = useState<'en' | 'vi'>('vi');
  const [devices, setDevices] = useState<Device[]>([]);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'inventory' | 'settings'>('dashboard');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingDevice, setEditingDevice] = useState<Device | null>(null);
  const [historyDevice, setHistoryDevice] = useState<Device | null>(null);
  const [aiInsights, setAiInsights] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [sheetUrl, setSheetUrl] = useState<string>(storageService.getSettings().sheetUrl);
  const [syncStatus, setSyncStatus] = useState<'idle' | 'success' | 'error'>('idle');
  const [showCopySuccess, setShowCopySuccess] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const t = translations[lang];

  useEffect(() => {
    const loadInitialData = async () => {
      const localData = storageService.getDevicesLocal();
      if (localData.length > 0) setDevices(localData);
      if (sheetUrl) {
        handleSync('pull');
      }
    };
    loadInitialData();
  }, []);

  const toggleLanguage = () => setLang(prev => prev === 'en' ? 'vi' : 'en');

  const handleSync = async (direction: 'pull' | 'push', updatedDevices?: Device[]) => {
    if (!sheetUrl) return;
    setIsSyncing(true);
    setSyncStatus('idle');
    try {
      const targetData = updatedDevices || devices;
      const result = await storageService.syncWithGoogleSheet(sheetUrl, direction === 'push' ? targetData : undefined);
      if (direction === 'pull' && result) {
        setDevices(result);
        storageService.saveDevicesLocal(result);
      }
      setSyncStatus('success');
    } catch (error) {
      setSyncStatus('error');
    } finally {
      setIsSyncing(false);
    }
  };

  const handleImportCSV = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target?.result as string;
      try {
        const importedDevices = storageService.parseCSV(text);

        const currentSerials = new Set(devices.map(d => d.serialNumber.toLowerCase()));
        const newDevices = importedDevices.filter(d => !currentSerials.has(d.serialNumber.toLowerCase()));

        if (newDevices.length === 0) {
          alert("Tất cả thiết bị trong file đã tồn tại hoặc file không hợp lệ.");
          return;
        }

        const updatedDevices = [...devices, ...newDevices];
        setDevices(updatedDevices);
        storageService.saveDevicesLocal(updatedDevices);

        const msg = t.importSuccess.replace('{count}', newDevices.length.toString());
        alert(msg);

        if (sheetUrl) {
          handleSync('push', updatedDevices);
        }
      } catch (err) {
        alert(t.importError);
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(window.location.href);
    setShowCopySuccess(true);
    setTimeout(() => setShowCopySuccess(false), 2000);
  };

  const saveDevice = async (newDeviceData: Device) => {
    const isDuplicateSerial = devices.some(d => 
      d.serialNumber.toLowerCase() === newDeviceData.serialNumber.toLowerCase() && 
      d.id !== newDeviceData.id
    );

    if (isDuplicateSerial) {
      alert(`Error: Serial Number "${newDeviceData.serialNumber}" already exists!`);
      return;
    }

    let updatedDevices: Device[];
    const now = new Date().toISOString().split('T')[0];

    if (editingDevice) {
      const isAssigneeChanged = editingDevice.assignedTo !== newDeviceData.assignedTo;
      const isStatusChanged = editingDevice.status !== newDeviceData.status;
      const newHistory: HistoryEntry[] = [...(newDeviceData.history || [])];

      if (isAssigneeChanged || isStatusChanged) {
        newHistory.push({
          id: Math.random().toString(36).substr(2, 9),
          assignee: newDeviceData.assignedTo || t.unassigned,
          date: newDeviceData.handoverDate || now,
          notes: isAssigneeChanged 
            ? `Bàn giao: Từ "${editingDevice.assignedTo || 'Kho'}" sang "${newDeviceData.assignedTo || 'Người mới'}"`
            : `Cập nhật trạng thái: ${newDeviceData.status}`
        });
      }

      const updatedDevice = { ...newDeviceData, history: newHistory };
      updatedDevices = devices.map(d => d.id === newDeviceData.id ? updatedDevice : d);
    } else {
      const initialHistory: HistoryEntry[] = [{
        id: Math.random().toString(36).substr(2, 9),
        assignee: newDeviceData.assignedTo || 'IT Stock',
        date: newDeviceData.purchaseDate || now,
        notes: 'Đăng ký thiết bị mới'
      }];
      updatedDevices = [...devices, { ...newDeviceData, history: initialHistory }];
    }

    setDevices(updatedDevices);
    storageService.saveDevicesLocal(updatedDevices);
    setIsFormOpen(false);
    setEditingDevice(null);

    if (sheetUrl) {
      handleSync('push', updatedDevices);
    }
  };

  const deleteDevice = (id: string) => {
    if (window.confirm('Bạn có chắc chắn muốn xóa thiết bị này?')) {
      const updated = devices.filter(d => d.id !== id);
      setDevices(updated);
      storageService.saveDevicesLocal(updated);
      if (sheetUrl) handleSync('push', updated);
    }
  };

  const updateSheetUrl = (url: string) => {
    setSheetUrl(url);
    storageService.saveSettings({ sheetUrl: url });
  };

  const generateInsights = async () => {
    setIsAnalyzing(true);
    try {
      const insight = await geminiService.analyzeInventory(devices);
      setAiInsights(insight);
    } catch (error) {
