import { Device, DeviceType } from '../types';

const LOCAL_STORAGE_KEY = 'device_master_data';
const SETTINGS_KEY = 'device_master_settings';

export const storageService = {
  getSettings: () => {
    const settings = localStorage.getItem(SETTINGS_KEY);
    return settings ? JSON.parse(settings) : { sheetUrl: '' };
  },

  saveSettings: (settings: { sheetUrl: string }) => {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
  },

  getDevicesLocal: (): Device[] => {
    const data = localStorage.getItem(LOCAL_STORAGE_KEY);
    return data ? JSON.parse(data) : [];
  },

  saveDevicesLocal: (devices: Device[]): void => {
    localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(devices));
  },

  syncWithGoogleSheet: async (url: string, devices?: Device[]): Promise<Device[] | null> => {
    if (!url) return null;

    try {
      if (devices) {
        const response = await fetch(url, {
          method: 'POST',
          mode: 'no-cors',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(devices),
        });
        return devices;
      } 

      const response = await fetch(url);
      if (!response.ok) throw new Error('Failed to fetch from sheet');
      const remoteData = await response.json();
      return Array.isArray(remoteData) ? remoteData : null;
    } catch (error) {
      console.error('Google Sheet Sync Error:', error);
      throw error;
    }
  },

  exportToCSV: (devices: Device[]) => {
    const headers = ['PC Name', 'Type', 'Manufacturer', 'Model', 'Serial', 'Purchase Date', 'Warranty Expiry', 'Handover Date', 'Assigned To', 'Status'];
    const rows = devices.map(d => [
      d.pcName || '',
      d.type,
      d.manufacturer,
      d.model,
      d.serialNumber,
      d.purchaseDate,
      d.warrantyExpiry,
      d.handoverDate,
      d.assignedTo,
      d.status
    ]);

    const csvContent = [
      headers.join(','),
      ...rows.map(e => e.map(val => `"${val}"`).join(','))
    ].join('\n');

    const blob = new Blob(["\ufeff" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', `devices_backup_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  },

  parseCSV: (csvText: string): Device[] => {
    const lines = csvText.split('\n');
    const result: Device[] = [];
    for (let i = 1; i < lines.length; i++) {
      if (!lines[i].trim()) continue;
      const values = lines[i].match(/(".*?"|[^",\s]+)(?=\s*,|\s*$)/g);
      if (values && values.length >= 10) {
        const clean = (val: string) => val.replace(/^"|"$/g, '').trim();
        result.push({
          id: Math.random().toString(36).substr(2, 9),
          pcName: clean(values[0]),
          type: clean(values[1]) as DeviceType,
          manufacturer: clean(values[2]),
          model: clean(values[3]),
          serialNumber: clean(values[4]),
          purchaseDate: clean(values[5]),
          warrantyExpiry: clean(values[6]),
          handoverDate: clean(values[7]),
          assignedTo: clean(values[8]),
          status: clean(values[9]) as any,
          history: []
        });
      }
    }
    return result;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { Device, DeviceType, HistoryEntry } from './types';
import { storageService } from './services/storageService';
import { geminiService } from './services/geminiService';
import { translations } from './translations';
import Dashboard from './components/Dashboard';
import DeviceTable from './components/DeviceTable';
import DeviceForm from './components/DeviceForm';
import HistoryModal from './components/HistoryModal';
import { 
  Plus, Download, Upload, Sparkles, LayoutDashboard, 
  Database, LogOut, Loader2, CheckCircle2, Cloud, 
  Settings as SettingsIcon, AlertCircle, RefreshCw, Languages,
  Share2, Copy, Check, Lock, ShieldCheck
} from 'lucide-react';

const MASTER_KEY = '123456'; // Bạn có thể thay đổi mã này tại đây

const App: React.FC = () => {
  const [lang, setLang] = useState<'en' | 'vi'>('vi');
  const [isAuthorized, setIsAuthorized] = useState<boolean>(false);
  const [authInput, setAuthInput] = useState('');
  const [authError, setAuthError] = useState(false);

  const [devices, setDevices] = useState<Device[]>([]);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'inventory' | 'settings'>('dashboard');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingDevice, setEditingDevice] = useState<Device | null>(null);
  const [historyDevice, setHistoryDevice] = useState<Device | null>(null);
  const [aiInsights, setAiInsights] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [sheetUrl, setSheetUrl] = useState<string>(storageService.getSettings().sheetUrl);
  const [syncStatus, setSyncStatus] = useState<'idle' | 'success' | 'error'>('idle');
  const [showCopySuccess, setShowCopySuccess] = useState(false);

  const fileInputRef = useRef<HTMLInputElement>(null);
  const t = translations[lang];

  useEffect(() => {
    // Kiểm tra session cũ
    const savedAuth = localStorage.getItem('is_authorized');
    if (savedAuth === 'true') setIsAuthorized(true);

    const loadInitialData = async () => {
      const localData = storageService.getDevicesLocal();
      if (localData.length > 0) setDevices(localData);
      if (sheetUrl) {
        handleSync('pull');
      }
    };
    loadInitialData();
  }, []);

  const handleLogin = (e: React.FormEvent) => {
    e.preventDefault();
    if (authInput === MASTER_KEY) {
      setIsAuthorized(true);
      setAuthError(false);
      localStorage.setItem('is_authorized', 'true');
    } else {
      setAuthError(true);
    }
  };

  const handleLogout = () => {
    setIsAuthorized(false);
    localStorage.removeItem('is_authorized');
  };

  const toggleLanguage = () => setLang(prev => prev === 'en' ? 'vi' : 'en');

  const handleSync = async (direction: 'pull' | 'push', updatedDevices?: Device[]) => {
    if (!sheetUrl) return;
    setIsSyncing(true);
    setSyncStatus('idle');
    try {
      const targetData = updatedDevices || devices;
      const result = await storageService.syncWithGoogleSheet(sheetUrl, direction === 'push' ? targetData : undefined);
      if (direction === 'pull' && result) {
        setDevices(result);
        storageService.saveDevicesLocal(result);
      }
      setSyncStatus('success');
    } catch (error) {
      setSyncStatus('error');
    } finally {
      setIsSyncing(false);
    }
  };

  const handleImportCSV = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (e) => {
      const text = e.target?.result as string;
      try {
        const importedDevices = storageService.parseCSV(text);
        const currentSerials = new Set(devices.map(d => d.serialNumber.toLowerCase()));
        const newDevices = importedDevices.filter(d => !currentSerials.has(d.serialNumber.toLowerCase()));

        if (newDevices.length === 0) {
          alert("Tất cả thiết bị trong file đã tồn tại hoặc file không hợp lệ.");
          return;
        }

        const updatedDevices = [...devices, ...newDevices];
        setDevices(updatedDevices);
        storageService.saveDevicesLocal(updatedDevices);
        alert(t.importSuccess.replace('{count}', newDevices.length.toString()));

        if (sheetUrl) handleSync('push', updatedDevices);
      } catch (err) {
        alert(t.importError);
      }
    };
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const copyToClipboard = () => {
    navigator.clipboard.writeText(window.location.href);
    setShowCopySuccess(true);
    setTimeout(() => setShowCopySuccess(false), 2000);
  };

  const saveDevice = async (newDeviceData: Device) => {
    const isDuplicateSerial = devices.some(d => 
      d.serialNumber.toLowerCase() === newDeviceData.serialNumber.toLowerCase() && 
      d.id !== newDeviceData.id
    );

    if (isDuplicateSerial) {
      alert(`Error: Serial Number "${newDeviceData.serialNumber}" already exists!`);
      return;
    }

    let updatedDevices: Device[];
    const now = new Date().toISOString().split('T')[0];

    if (editingDevice) {
      const isAssigneeChanged = editingDevice.assignedTo !== newDeviceData.assignedTo;
      const isStatusChanged = editingDevice.status !== newDeviceData.status;
      const newHistory: HistoryEntry[] = [...(newDeviceData.history || [])];

      if (isAssigneeChanged || isStatusChanged) {
        newHistory.push({
          id: Math.random().toString(36).substr(2, 9),
          assignee: newDeviceData.assignedTo || t.unassigned,
          date: newDeviceData.handoverDate || now,
          notes: isAssigneeChanged 
            ? `Bàn giao: Từ "${editingDevice.assignedTo || 'Kho'}" sang "${newDeviceData.assignedTo || 'Người mới'}"`
            : `Cập nhật trạng thái: ${newDeviceData.status}`
        });
      }
      updatedDevices = devices.map(d => d.id === newDeviceData.id ? { ...newDeviceData, history: newHistory } : d);
    } else {
      const initialHistory: HistoryEntry[] = [{
        id: Math.random().toString(36).substr(2, 9),
        assignee: newDeviceData.assignedTo || 'IT Stock',
        date: newDeviceData.purchaseDate || now,
        notes: 'Đăng ký thiết bị mới'
      }];
      updatedDevices = [...devices, { ...newDeviceData, history: initialHistory }];
    }

    setDevices(updatedDevices);
    storageService.saveDevicesLocal(updatedDevices);
    setIsFormOpen(false);
    setEditingDevice(null);

    if (sheetUrl) handleSync('push', updatedDevices);
  };

  const deleteDevice = (id: string) => {
    if (window.confirm('Bạn có chắc chắn muốn xóa thiết bị này?')) {
      const updated = devices.filter(d => d.id !== id);
      setDevices(updated);
      storageService.saveDevicesLocal(updated);
      if (sheetUrl) handleSync('push', updated);
    }
  };

  const generateInsights = async () => {
    setIsAnalyzing(true);
    try {
      const insight = await geminiService.analyzeInventory(devices);
      setAiInsights(insight);
    } catch (error) {
      setAiInsights("AI Analysis failed.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  if (!isAuthorized) {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center p-6 relative overflow-hidden">
        {/* Background blobs */}
        <div className="absolute top-0 -left-20 w-96 h-96 bg-indigo-600/20 rounded-full blur-[100px]"></div>
        <div className="absolute bottom-0 -right-20 w-96 h-96 bg-blue-600/10 rounded-full blur-[100px]"></div>

        <div className="w-full max-w-md bg-slate-900/50 backdrop-blur-2xl p-10 rounded-[40px] border border-slate-800 shadow-2xl animate-in fade-in zoom-in duration-500 relative z-10">
          <div className="flex flex-col items-center mb-8 text-center">
            <div className="w-20 h-20 bg-white rounded-2xl flex items-center justify-center overflow-hidden mb-6 shadow-xl shadow-black/40">
              <img src="https://d2nyjryheal9w7.cloudfront.net/610a5b0dbd9b2500172ecee5/%E7%A8%B2%E7%95%91%E7%94%A3%E6%A5%AD%E3%83%AD%E3%82%B4%20(1).png" alt="Logo" className="w-full h-full object-contain p-2" />
            </div>
            <h1 className="text-2xl font-black text-white mb-2 tracking-tight">{t.loginTitle}</h1>
            <p className="text-slate-400 text-sm font-medium leading-relaxed">{t.loginDesc}</p>
          </div>

          <form onSubmit={handleLogin} className="space-y-6">
            <div className="relative group">
              <Lock className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-500 group-focus-within:text-indigo-400 transition-colors" size={20} />
              <input 
                type="password"
                placeholder={t.enterKey}
                className={`w-full pl-12 pr-6 py-4 bg-slate-800/50 border ${authError ? 'border-red-500/50' : 'border-slate-700'} rounded-2xl text-white outline-none focus:ring-4 focus:ring-indigo-500/20 focus:border-indigo-500 transition-all font-mono tracking-widest`}
                value={authInput}
                onChange={(e) => { setAuthInput(e.target.value); setAuthError(false); }}
                autoFocus
              />
            </div>

            {authError && (
              <div className="flex items-center gap-2 text-red-400 text-xs font-bold animate-in slide-in-from-top-2">
                <AlertCircle size={14} />
                {t.accessDenied}
              </div>
            )}

            <button 
              type="submit" 
              className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl font-bold text-sm shadow-xl shadow-indigo-500/20 transition-all active:scale-95 flex items-center justify-center gap-2 group"
            >
              <ShieldCheck size={18} className="group-hover:scale-110 transition-transform" />
              {t.unlock}
            </button>
          </form>

          <div className="mt-8 pt-8 border-t border-slate-800 flex justify-center gap-4">
             <button onClick={toggleLanguage} className="text-[10px] font-bold uppercase tracking-widest text-slate-500 hover:text-indigo-400 transition-colors">
               {lang === 'en' ? 'Tiếng Việt' : 'English'}
             </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen bg-slate-50 text-slate-900">
      <aside className="hidden md:flex w-72 flex-col bg-slate-900 text-slate-300 sticky top-0 h-screen">
        <div className="p-8">
          <div className="flex items-center gap-3 mb-10">
            <div className="w-12 h-12 bg-white rounded-xl flex items-center justify-center overflow-hidden border border-slate-700">
              <img src="https://d2nyjryheal9w7.cloudfront.net/610a5b0dbd9b2500172ecee5/%E7%A8%B2%E7%95%91%E7%94%A3%E6%A5%AD%E3%83%AD%E3%82%B4%20(1).png" alt="Logo" className="w-full h-full object-contain p-1" />
            </div>
            <div>
              <h1 className="font-bold text-white text-lg leading-tight">{t.appName}</h1>
              <p className="text-[10px] text-indigo-400 font-bold uppercase tracking-widest">{t.subName}</p>
            </div>
          </div>

          <nav className="space-y-2">
            <SidebarLink active={activeTab === 'dashboard'} onClick={() => setActiveTab('dashboard')} icon={<LayoutDashboard size={20} />} label={t.dashboard} />
            <SidebarLink active={activeTab === 'inventory'} onClick={() => setActiveTab('inventory')} icon={<Database size={20} />} label={t.inventory} />
            <SidebarLink active={activeTab === 'settings'} onClick={() => setActiveTab('settings')} icon={<SettingsIcon size={20} />} label={t.settings} />
          </nav>

          <div className="mt-10 p-4 bg-slate-800/50 rounded-2xl border border-slate-700/50">
            <div className="flex items-center justify-between mb-3 text-xs font-bold text-slate-400 uppercase">
              <div className="flex items-center gap-2">
                <Cloud size={14} className={sheetUrl ? "text-green-400" : "text-amber-400"} />
                {t.cloudSync}
              </div>
              {isSyncing && <RefreshCw size={12} className="animate-spin text-indigo-400" />}
            </div>
            {sheetUrl ? (
              <div className="space-y-2">
                <div className={`flex items-center gap-2 text-xs font-medium ${syncStatus === 'error' ? 'text-red-400' : 'text-green-400'}`}>
                  {syncStatus === 'error' ? <AlertCircle size={14}/> : <CheckCircle2 size={14} />}
                  {syncStatus === 'error' ? t.syncFailed : t.connected}
                </div>
                <button onClick={() => handleSync('pull')} disabled={isSyncing} className="w-full mt-2 py-1.5 bg-slate-700 hover:bg-slate-600 rounded-lg text-[10px] font-bold uppercase tracking-wider transition-colors">{t.syncNow}</button>
              </div>
            ) : <p className="text-[10px] text-slate-500 italic">Chưa cấu hình Google Sheet.</p>}
          </div>
        </div>

        <div className="mt-auto p-8 border-t border-slate-800">
          <button onClick={handleLogout} className="flex items-center gap-3 text-slate-400 hover:text-white transition-colors w-full group">
            <LogOut size={20} className="group-hover:translate-x-1 transition-transform" />
            <span className="font-medium text-sm">{t.signOut}</span>
          </button>
        </div>
      </aside>

      <main className="flex-1 overflow-y-auto">
        <header className="bg-white/80 backdrop-blur-md border-b border-slate-200 sticky top-0 z-30 px-8 py-5 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <h2 className="text-2xl font-black text-slate-800 tracking-tight capitalize">{activeTab === 'settings' ? t.settings : activeTab === 'dashboard' ? t.dashboard : t.inventory}</h2>
            <button onClick={toggleLanguage} className="flex items-center gap-2 px-3 py-1.5 bg-slate-100 rounded-lg text-[10px] font-bold uppercase text-slate-600 hover:bg-indigo-50 transition-all border border-slate-200">
              <Languages size={14} />
              {lang === 'en' ? 'Tiếng Việt' : 'English'}
            </button>
          </div>

          <div className="flex items-center gap-3">
            <button onClick={generateInsights} disabled={isAnalyzing} className="hidden lg:flex items-center gap-2 px-4 py-2.5 bg-indigo-50 text-indigo-700 rounded-xl font-bold text-sm hover:bg-indigo-100 transition-all border border-indigo-100">
              {isAnalyzing ? <Loader2 className="animate-spin" size={16} /> : <Sparkles size={16} />}
              {t.aiInsights}
            </button>
            <div className="h-8 w-[1px] bg-slate-200 mx-2 hidden md:block"></div>
            <div className="flex items-center gap-2">
              <input type="file" ref={fileInputRef} onChange={handleImportCSV} accept=".csv" className="hidden" />
              <button onClick={() => fileInputRef.current?.click()} className="p-2.5 bg-slate-50 text-slate-600 rounded-xl hover:bg-slate-200 transition-colors border border-slate-200" title={t.importCsv}><Upload size={20} /></button>
              <button onClick={() => storageService.exportToCSV(devices)} className="p-2.5 bg-slate-50 text-slate-600 rounded-xl hover:bg-slate-200 transition-colors border border-slate-200" title={t.backupCsv}><Download size={20} /></button>
            </div>
            <button onClick={() => { setEditingDevice(null); setIsFormOpen(true); }} className="flex items-center gap-2 px-6 py-2.5 bg-indigo-600 text-white rounded-xl font-bold text-sm shadow-xl shadow-indigo-500/20 hover:bg-indigo-700 transition-all active:scale-95">
              <Plus size={18} />
              {t.addDevice}
            </button>
          </div>
        </header>

        <div className="p-8 max-w-7xl mx-auto space-y-8">
          {aiInsights && (
            <div className="bg-gradient-to-br from-indigo-600 to-blue-700 p-[1px] rounded-3xl overflow-hidden shadow-2xl shadow-indigo-200">
              <div className="bg-white/95 backdrop-blur-sm p-8 rounded-[23px] relative">
                <button onClick={() => setAiInsights(null)} className="absolute top-6 right-6 p-2 text-slate-400 hover:text-slate-600 hover:bg-slate-100 rounded-full transition-all"><Plus className="rotate-45" size={24} /></button>
                <div className="flex gap-6">
                  <div className="w-16 h-16 bg-indigo-100 rounded-2xl flex items-center justify-center text-indigo-600 shrink-0"><Sparkles size={32} /></div>
                  <div>
                    <h3 className="font-black text-slate-900 text-xl mb-3">{t.aiInsights}</h3>
                    <div className="text-slate-600 text-base whitespace-pre-line font-medium">{aiInsights}</div>
                  </div>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'dashboard' && <Dashboard devices={devices} lang={lang} />}
          {activeTab === 'inventory' && <DeviceTable devices={devices} onEdit={(d) => { setEditingDevice(d); setIsFormOpen(true); }} onDelete={deleteDevice} onViewHistory={(d) => setHistoryDevice(d)} lang={lang} />}
          {activeTab === 'settings' && (
            <div className="max-w-2xl mx-auto space-y-8">
              <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm space-y-8">
                <div className="flex items-center gap-4">
                  <div className="p-4 bg-indigo-50 rounded-2xl text-indigo-600"><Cloud size={32} /></div>
                  <div><h3 className="text-xl font-black text-slate-800">{t.cloudSync}</h3><p className="text-sm text-slate-500">Đồng bộ dữ liệu của bạn thông qua Google Sheets.</p></div>
                </div>
                <div className="space-y-4">
                  <label className="block text-sm font-bold text-slate-700">Google Apps Script Web App URL</label>
                  <input type="text" className="w-full px-5 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none font-mono text-xs" value={sheetUrl} onChange={(e) => { setSheetUrl(e.target.value); storageService.saveSettings({ sheetUrl: e.target.value }); }} />
                </div>
              </div>
              <div className="bg-white p-8 rounded-3xl border border-slate-200 shadow-sm space-y-8">
                <div className="flex items-center gap-4">
                  <div className="p-4 bg-green-50 rounded-2xl text-green-600"><Share2 size={32} /></div>
                  <div><h3 className="text-xl font-black text-slate-800">{t.shareApp}</h3><p className="text-sm text-slate-500">{t.shareDesc}</p></div>
                </div>
                <div className="flex items-center gap-3 p-4 bg-slate-50 border border-slate-200 rounded-2xl">
                  <div className="flex-1 truncate font-mono text-xs text-slate-600">{window.location.href}</div>
                  <button onClick={copyToClipboard} className={`flex items-center gap-2 px-4 py-2 rounded-xl font-bold text-xs transition-all ${showCopySuccess ? 'bg-green-600 text-white' : 'bg-indigo-600 text-white hover:bg-indigo-700'}`}>{showCopySuccess ? <Check size={14} /> : <Copy size={14} />}{showCopySuccess ? t.linkCopied : t.copyLink}</button>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>
      {isFormOpen && <DeviceForm device={editingDevice} onSave={saveDevice} onClose={() => setIsFormOpen(false)} lang={lang} />}
      {historyDevice && <HistoryModal device={historyDevice} onClose={() => setHistoryDevice(null)} lang={lang} />}
    </div>
  );
};

const SidebarLink = ({ active, onClick, icon, label }: any) => (
  <button onClick={onClick} className={`flex items-center gap-4 w-full px-5 py-3.5 rounded-2xl transition-all duration-300 group ${active ? 'bg-indigo-600 text-white font-bold shadow-lg shadow-indigo-600/20' : 'text-slate-400 hover:bg-slate-800 hover:text-slate-200'}`}>
    <div className={`${active ? 'text-white' : 'text-slate-500 group-hover:text-indigo-400'} transition-colors`}>{icon}</div>
    <span className="text-sm tracking-wide">{label}</span>
