      const initialHistory: HistoryEntry[] = [{
        id: Math.random().toString(36).substr(2, 9),
        assignee: newDeviceData.assignedTo || 'IT Stock',
        date: newDeviceData.purchaseDate || now,
        notes: 'Đăng ký thiết bị mới'
      }];
      updatedDevices = [...devices, { ...newDeviceData, history: initialHistory }];
    }

    setDevices(updatedDevices);
    await storageService.saveDevicesSecure(updatedDevices, masterKey);
    setIsFormOpen(false);
    setEditingDevice(null);

    if (sheetUrl) handleSync('push', updatedDevices);
  };

  const deleteDevice = async (id: string) => {
    if (window.confirm('Bạn có chắc chắn muốn xóa thiết bị này?')) {
      const updated = devices.filter(d => d.id !== id);
