                  <div><h3 className="text-xl font-black text-slate-800">{t.securitySettings}</h3><p className="text-sm text-slate-500">{t.changePass}</p></div>
                </div>

                <form onSubmit={handleChangePassword} className="space-y-4">
                  <div>
                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1.5 ml-1">{t.currentPass}</label>
                    <input required type="password" value={passCurrent} onChange={e => setPassCurrent(e.target.value)} className="w-full px-5 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none text-sm focus:ring-4 focus:ring-indigo-500/10 transition-all" />
                  </div>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1.5 ml-1">{t.newPass}</label>
                      <input required type="password" value={passNew} onChange={e => setPassNew(e.target.value)} className="w-full px-5 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none text-sm focus:ring-4 focus:ring-indigo-500/10 transition-all" />
                    </div>
                    <div>
                      <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1.5 ml-1">{t.confirmPass}</label>
                      <input required type="password" value={passConfirm} onChange={e => setPassConfirm(e.target.value)} className="w-full px-5 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none text-sm focus:ring-4 focus:ring-indigo-500/10 transition-all" />
                    </div>
                  </div>

                  {passStatus && (
                    <div className={`p-4 rounded-xl text-xs font-bold flex items-center gap-2 ${passStatus.type === 'success' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'}`}>
                      {passStatus.type === 'success' ? <CheckCircle2 size={16}/> : <AlertCircle size={16}/>}
                      {passStatus.msg}
                    </div>
                  )}

                  <button type="submit" className="w-full py-3 bg-slate-900 text-white rounded-xl font-bold text-sm hover:bg-black transition-all shadow-lg active:scale-95">
                    {t.updatePass}
                  </button>
                </form>
              </div>
            </div>
          )}
        </div>
      </main>
      {isFormOpen && <DeviceForm device={editingDevice} onSave={saveDevice} onClose={() => setIsFormOpen(false)} lang={lang} />}
      {historyDevice && <HistoryModal device={historyDevice} onClose={() => setHistoryDevice(null)} lang={lang} />}
    </div>
  );
};

