    setIsSyncing(true);
    try {
      const targetData = updatedDevices || devices;
      const result = await storageService.syncWithGoogleSheet(sheetUrl, masterKey, direction === 'push' ? targetData : undefined);
      if (direction === 'pull' && result) {
