import { Device, DeviceType } from '../types';

const LOCAL_STORAGE_KEY = 'device_master_encrypted';
const SETTINGS_KEY = 'device_master_settings';

// Helper để xử lý mã hóa
const cryptoUtils = {
  deriveKey: async (password: string, salt: Uint8Array) => {
    const encoder = new TextEncoder();
    const baseKey = await crypto.subtle.importKey(
      'raw',
      encoder.encode(password),
      'PBKDF2',
      false,
      ['deriveKey']
    );
    return crypto.subtle.deriveKey(
      {
        name: 'PBKDF2',
        salt,
        iterations: 100000,
        hash: 'SHA-256'
      },
      baseKey,
      { name: 'AES-GCM', length: 256 },
      false,
      ['encrypt', 'decrypt']
    );
  },

  encrypt: async (data: string, password: string) => {
    const salt = crypto.getRandomValues(new Uint8Array(16));
    const iv = crypto.getRandomValues(new Uint8Array(12));
    const key = await cryptoUtils.deriveKey(password, salt);

    const encoder = new TextEncoder();
    const encrypted = await crypto.subtle.encrypt(
      { name: 'AES-GCM', iv },
      key,
      encoder.encode(data)
    );

    const combined = new Uint8Array(salt.length + iv.length + encrypted.byteLength);
    combined.set(salt, 0);
    combined.set(iv, salt.length);
    combined.set(new Uint8Array(encrypted), salt.length + iv.length);

    return btoa(String.fromCharCode(...combined));
  },

  decrypt: async (encryptedBase64: string, password: string) => {
    try {
      const combined = new Uint8Array(atob(encryptedBase64).split('').map(c => c.charCodeAt(0)));
      const salt = combined.slice(0, 16);
      const iv = combined.slice(16, 28);
      const data = combined.slice(28);

      const key = await cryptoUtils.deriveKey(password, salt);
      const decrypted = await crypto.subtle.decrypt(
        { name: 'AES-GCM', iv },
        key,
        data
      );

      return new TextDecoder().decode(decrypted);
    } catch (e) {
      throw new Error('Decryption failed');
    }
  }
};

export const storageService = {
  getSettings: () => {
    const settings = localStorage.getItem(SETTINGS_KEY);
    return settings ? JSON.parse(settings) : { sheetUrl: '' };
  },

  saveSettings: (settings: { sheetUrl: string }) => {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings));
  },

  saveDevicesSecure: async (devices: Device[], password: string): Promise<void> => {
    const json = JSON.stringify(devices);
    const encrypted = await cryptoUtils.encrypt(json, password);
    localStorage.setItem(LOCAL_STORAGE_KEY, encrypted);
  },

  getDevicesSecure: async (password: string): Promise<Device[]> => {
    const encrypted = localStorage.getItem(LOCAL_STORAGE_KEY);
    if (!encrypted) return [];

    const decryptedJson = await cryptoUtils.decrypt(encrypted, password);
    return JSON.parse(decryptedJson);
  },

  syncWithGoogleSheet: async (url: string, password: string, devices?: Device[]): Promise<Device[] | null> => {
    if (!url) return null;
    try {
      if (devices) {
        const encryptedData = await cryptoUtils.encrypt(JSON.stringify(devices), password);
        await fetch(url, {
          method: 'POST',
          mode: 'no-cors',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ payload: encryptedData }),
        });
        return devices;
      } 
      const response = await fetch(url);
      if (!response.ok) throw new Error('Failed to fetch from sheet');
      const remoteData = await response.json();
      if (remoteData && remoteData.payload) {
        const decrypted = await cryptoUtils.decrypt(remoteData.payload, password);
        return JSON.parse(decrypted);
      }
      return Array.isArray(remoteData) ? remoteData : null;
    } catch (error) {
      console.error('Cloud Sync Error:', error);
      throw error;
    }
  },

  exportToCSV: (devices: Device[]) => {
    const headers = ['PC Name', 'Type', 'Manufacturer', 'Model', 'Serial', 'Purchase Date', 'Warranty Expiry', 'Handover Date', 'Assigned To', 'Status'];
    const rows = devices.map(d => [
      d.pcName || '',
      d.type,
      d.manufacturer,
      d.model,
      d.serialNumber,
      d.purchaseDate,
      d.warrantyExpiry,
      d.handoverDate,
      d.assignedTo,
      d.status
    ]);

    const csvContent = [
      headers.join(','),
      ...rows.map(e => e.map(val => `"${val.toString().replace(/"/g, '""')}"`).join(','))
    ].join('\n');

    const blob = new Blob(["\ufeff" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', `devices_backup_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  },

  parseCSV: (csvText: string): Device[] => {
    const lines = csvText.split(/\r?\n/);
    if (lines.length < 2) return [];

    // Xác định dấu phân cách (thường là , hoặc ;)
    const header = lines[0];
    const delimiter = header.includes(';') ? ';' : ',';

    const result: Device[] = [];

    for (let i = 1; i < lines.length; i++) {
      const line = lines[i].trim();
      if (!line) continue;

      const values: string[] = [];
      let current = '';
      let inQuotes = false;
      for (let char of line) {
        if (char === '"') inQuotes = !inQuotes;
        else if (char === delimiter && !inQuotes) {
          values.push(current.trim());
          current = '';
        } else {
          current += char;
        }
      }
      values.push(current.trim());

      if (values.length >= 5) { // Tối thiểu phải có thông tin cơ bản
        const clean = (val: string) => (val || '').replace(/^"|"$/g, '').trim();

        // Cố gắng ánh xạ dữ liệu, nếu thiếu thì để trống
        result.push({
          id: Math.random().toString(36).substr(2, 9),
          pcName: clean(values[0]),
          type: (clean(values[1]) || DeviceType.LAPTOP) as DeviceType,
          manufacturer: clean(values[2]),
          model: clean(values[3]),
          serialNumber: clean(values[4]),
          purchaseDate: clean(values[5]),
          warrantyExpiry: clean(values[6]),
          handoverDate: clean(values[7]),
          assignedTo: clean(values[8]),
          status: (clean(values[9]) || 'Available') as any,
          history: []
        });
      }
    }
    return result;
  }
};

import React, { useState, useEffect, useRef } from 'react';
import { Device, DeviceType, HistoryEntry } from './types';
import { storageService } from './services/storageService';
import { geminiService } from './services/geminiService';
import { translations } from './translations';
import Dashboard from './components/Dashboard';
import DeviceTable from './components/DeviceTable';
import DeviceForm from './components/DeviceForm';
import HistoryModal from './components/HistoryModal';
import { 
  Plus, Download, Upload, Sparkles, LayoutDashboard, 
  Database, LogOut, Loader2, CheckCircle2, Cloud, 
  Settings as SettingsIcon, AlertCircle, RefreshCw, Languages,
  Share2, Copy, Check, Lock, ShieldCheck, Key, X, Menu, ChevronLeft, ChevronRight
} from 'lucide-react';

const App: React.FC = () => {
  const [lang, setLang] = useState<'en' | 'vi'>('vi');
  const [isAuthorized, setIsAuthorized] = useState<boolean>(false);
  const [authInput, setAuthInput] = useState('');
  const [authError, setAuthError] = useState(false);
  const [masterKey, setMasterKey] = useState<string>('');

  // States cho Sidebar
  const [sidebarExpanded, setSidebarExpanded] = useState(true);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  // States cho lọc ngoại vi
  const [externalExpiringFilter, setExternalExpiringFilter] = useState(false);

  // States cho đổi mật khẩu
  const [passCurrent, setPassCurrent] = useState('');
  const [passNew, setPassNew] = useState('');
  const [passConfirm, setPassConfirm] = useState('');
  const [passStatus, setPassStatus] = useState<{type: 'success' | 'error', msg: string} | null>(null);

  const [devices, setDevices] = useState<Device[]>([]);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'inventory' | 'settings'>('dashboard');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingDevice, setEditingDevice] = useState<Device | null>(null);
  const [historyDevice, setHistoryDevice] = useState<Device | null>(null);
  const [aiInsights, setAiInsights] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [sheetUrl, setSheetUrl] = useState<string>(storageService.getSettings().sheetUrl);
  const [syncStatus, setSyncStatus] = useState<'idle' | 'success' | 'error'>('idle');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const t = translations[lang];

  const toggleLanguage = () => setLang(prev => prev === 'en' ? 'vi' : 'en');

  const generateInsights = async () => {
    if (devices.length === 0) return;
    setIsAnalyzing(true);
    try {
      const result = await geminiService.analyzeInventory(devices);
      setAiInsights(result);
    } catch (error) {
      setAiInsights(lang === 'vi' ? "Phân tích AI thất bại." : "AI Analysis failed.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setAuthError(false);
    try {
      const data = await storageService.getDevicesSecure(authInput);
      setDevices(data);
      setMasterKey(authInput);
      setIsAuthorized(true);
    } catch (err) {
      if (!localStorage.getItem('device_master_encrypted') && authInput === '123456') {
        setMasterKey(authInput);
        setIsAuthorized(true);
        return;
      }
      setAuthError(true);
    }
  };

  const handleLogout = () => {
    setIsAuthorized(false);
    setMasterKey('');
    setDevices([]);
    setMobileMenuOpen(false);
  };

  const handleChangePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    if (passCurrent !== masterKey) {
      setPassStatus({ type: 'error', msg: t.wrongCurrentPass });
      return;
    }
    if (passNew !== passConfirm) {
      setPassStatus({ type: 'error', msg: t.passMismatch });
      return;
    }
    try {
      await storageService.saveDevicesSecure(devices, passNew);
      setMasterKey(passNew);
      setPassStatus({ type: 'success', msg: t.passSuccess });
      setPassCurrent(''); setPassNew(''); setPassConfirm('');
    } catch (err) {
      setPassStatus({ type: 'error', msg: "Update failed" });
    }
  };

  const handleSync = async (direction: 'pull' | 'push', updatedDevices?: Device[]) => {
    if (!sheetUrl || !masterKey) return;
    setIsSyncing(true);
    try {
      const targetData = updatedDevices || devices;
      const result = await storageService.syncWithGoogleSheet(sheetUrl, masterKey, direction === 'push' ? targetData : undefined);
      if (direction === 'pull' && result) {
        setDevices(result);
        await storageService.saveDevicesSecure(result, masterKey);
      }
      setSyncStatus('success');
    } catch (error) {
      setSyncStatus('error');
    } finally {
      setIsSyncing(false);
    }
  };

  const handleImportCSV = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (e) => {
      const text = e.target?.result as string;
      try {
        const imported = storageService.parseCSV(text);
        if (imported.length === 0) {
          alert(lang === 'vi' ? 'Không tìm thấy dữ liệu hợp lệ trong file!' : 'No valid data found in CSV!');
          return;
        }

        // Lọc trùng Serial
        const currentSerials = new Set(devices.map(d => d.serialNumber.toLowerCase()));
        const newDevices = imported.filter(d => !currentSerials.has(d.serialNumber.toLowerCase()));

        if (newDevices.length === 0) {
          alert(lang === 'vi' ? 'Toàn bộ thiết bị trong file đã tồn tại trong hệ thống.' : 'All devices in the file already exist.');
          return;
        }

        const updated = [...devices, ...newDevices];
        setDevices(updated);
        await storageService.saveDevicesSecure(updated, masterKey);

        // Thông báo thành công
        const successMsg = lang === 'vi' 
          ? `Thành công! Đã thêm ${newDevices.length} thiết bị mới vào kho.` 
          : `Success! Added ${newDevices.length} new devices to inventory.`;
        alert(successMsg);

        if (sheetUrl) handleSync('push', updated);
      } catch (err) {
        console.error(err);
        alert(t.importError); 
      }
    };
    reader.onerror = () => alert(lang === 'vi' ? 'Lỗi đọc file.' : 'Error reading file.');
    reader.readAsText(file);

    // Reset value để có thể chọn lại cùng 1 file
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const saveDevice = async (newDeviceData: Device) => {
    let updatedDevices: Device[];
    const now = new Date().toISOString().split('T')[0];
    if (editingDevice) {
      const isAssigneeChanged = editingDevice.assignedTo !== newDeviceData.assignedTo;
      const isStatusChanged = editingDevice.status !== newDeviceData.status;
      const newHistory = [...(newDeviceData.history || [])];
      if (isAssigneeChanged || isStatusChanged) {
        newHistory.push({
          id: Math.random().toString(36).substr(2, 9),
          assignee: newDeviceData.assignedTo || t.unassigned,
          date: newDeviceData.handoverDate || now,
          notes: isAssigneeChanged ? `Bàn giao mới` : `Cập nhật: ${newDeviceData.status}`
        });
      }
      updatedDevices = devices.map(d => d.id === newDeviceData.id ? { ...newDeviceData, history: newHistory } : d);
    } else {
      updatedDevices = [...devices, { ...newDeviceData, history: [{ id: 'init', assignee: 'Stock', date: now, notes: 'Khởi tạo' }] }];
    }
    setDevices(updatedDevices);
    await storageService.saveDevicesSecure(updatedDevices, masterKey);
    setIsFormOpen(false);
    if (sheetUrl) handleSync('push', updatedDevices);
  };

  const deleteDevice = async (id: string) => {
    if (window.confirm('Xóa thiết bị này?')) {
      const updated = devices.filter(d => d.id !== id);
      setDevices(updated);
      await storageService.saveDevicesSecure(updated, masterKey);
      if (sheetUrl) handleSync('push', updated);
    }
  };

  const handleShowExpiring = () => {
    setExternalExpiringFilter(true);
    setActiveTab('inventory');
    setTimeout(() => setExternalExpiringFilter(false), 500);
  };

  if (!isAuthorized) {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center p-6 relative overflow-hidden">
        <div className="absolute top-0 -left-20 w-96 h-96 bg-indigo-600/20 rounded-full blur-[100px]"></div>
        <div className="w-full max-w-md bg-slate-900/50 backdrop-blur-2xl p-10 rounded-[40px] border border-slate-800 shadow-2xl relative z-10">
          <div className="flex flex-col items-center mb-8 text-center">
            <div className="w-20 h-20 bg-white rounded-2xl flex items-center justify-center overflow-hidden mb-6 shadow-xl">
              <img src="https://d2nyjryheal9w7.cloudfront.net/610a5b0dbd9b2500172ecee5/%E7%A8%B2%E7%95%91%E7%94%A3%E6%A5%AD%E3%83%AD%E3%82%B4%20(1).png" alt="Logo" className="w-full h-full object-contain p-2" />
            </div>
            <h1 className="text-2xl font-black text-white mb-2 tracking-tight">{t.loginTitle}</h1>
            <p className="text-slate-400 text-sm">{t.loginDesc}</p>
          </div>
          <form onSubmit={handleLogin} className="space-y-6">
            <input 
              type="password" 
              placeholder={t.enterKey} 
              className="w-full pl-6 pr-6 py-4 bg-slate-800/50 border border-slate-700 rounded-2xl text-white outline-none focus:ring-4 focus:ring-indigo-500/20 focus:border-indigo-500 transition-all font-mono tracking-widest text-center"
              value={authInput}
              onChange={(e) => setAuthInput(e.target.value)}
              autoFocus
            />
            {authError && <div className="text-red-400 text-xs font-bold text-center">Mã khóa không đúng.</div>}
            <button type="submit" className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl font-bold shadow-xl shadow-indigo-500/20 transition-all flex items-center justify-center gap-2">
              <ShieldCheck size={18} /> {t.unlock}
            </button>
          </form>
          <div className="mt-8 pt-8 border-t border-slate-800 flex justify-center">
             <button onClick={toggleLanguage} className="text-[10px] font-bold uppercase tracking-widest text-slate-500 hover:text-indigo-400">
               {lang === 'en' ? 'Tiếng Việt' : 'English'}
             </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen bg-slate-50 text-slate-900 overflow-hidden">
      {mobileMenuOpen && (
        <div className="fixed inset-0 bg-slate-950/60 backdrop-blur-sm z-40 md:hidden transition-opacity duration-300" onClick={() => setMobileMenuOpen(false)} />
      )}
      <aside className={`fixed inset-y-0 left-0 z-50 bg-slate-900 text-slate-300 transition-all duration-500 ease-in-out flex flex-col ${sidebarExpanded ? 'w-72' : 'w-20'} ${mobileMenuOpen ? 'translate-x-0 w-72' : '-translate-x-full md:translate-x-0'} md:relative md:flex`}>
        <button onClick={() => setSidebarExpanded(!sidebarExpanded)} className="hidden md:flex absolute -right-3 top-20 w-6 h-6 bg-indigo-600 rounded-full items-center justify-center text-white border-2 border-slate-900 hover:bg-indigo-50 transition-all z-10">
          {sidebarExpanded ? <ChevronLeft size={14} /> : <ChevronRight size={14} />}
        </button>
        <div className={`p-6 mb-4 flex items-center gap-3 overflow-hidden ${(!sidebarExpanded && !mobileMenuOpen) && 'justify-center'}`}>
          <div className="min-w-[40px] w-10 h-10 bg-white rounded-xl flex items-center justify-center overflow-hidden border border-slate-700 shrink-0">
            <img src="https://d2nyjryheal9w7.cloudfront.net/610a5b0dbd9b2500172ecee5/%E7%A8%B2%E7%95%91%E7%94%A3%E6%A5%AD%E3%83%AD%E3%82%B4%20(1).png" alt="Logo" className="w-full h-full object-contain p-1" />
          </div>
          {(sidebarExpanded || mobileMenuOpen) && (
            <div className="truncate whitespace-nowrap animate-in fade-in slide-in-from-left-2">
              <h1 className="font-bold text-white text-base leading-tight">Device Master</h1>
              <p className="text-[9px] text-indigo-400 font-bold uppercase tracking-widest">{t.subName}</p>
            </div>
          )}
        </div>
        <nav className="flex-1 px-3 space-y-2">
          <SidebarLink active={activeTab === 'dashboard'} onClick={() => { setActiveTab('dashboard'); setMobileMenuOpen(false); }} icon={<LayoutDashboard size={20} />} label={t.dashboard} expanded={sidebarExpanded || mobileMenuOpen} />
          <SidebarLink active={activeTab === 'inventory'} onClick={() => { setActiveTab('inventory'); setMobileMenuOpen(false); }} icon={<Database size={20} />} label={t.inventory} expanded={sidebarExpanded || mobileMenuOpen} />
          <SidebarLink active={activeTab === 'settings'} onClick={() => { setActiveTab('settings'); setMobileMenuOpen(false); }} icon={<SettingsIcon size={20} />} label={t.settings} expanded={sidebarExpanded || mobileMenuOpen} />
        </nav>
        <div className={`mt-4 px-3 mb-4 ${(sidebarExpanded || mobileMenuOpen) ? 'block' : 'flex justify-center'}`}>
          <div className={`bg-slate-800/50 rounded-2xl border border-slate-700/50 transition-all duration-300 ${ (sidebarExpanded || mobileMenuOpen) ? 'p-4' : 'p-2'}`}>
            <div className="flex items-center justify-between gap-2">
              <div className="flex items-center gap-2">
                <div className="relative">
                  <Cloud size={(sidebarExpanded || mobileMenuOpen) ? 18 : 20} className={sheetUrl ? "text-indigo-400" : "text-amber-400"} />
                  {sheetUrl && <div className={`absolute -top-1 -right-1 w-2.5 h-2.5 rounded-full border-2 border-slate-800 ${syncStatus === 'error' ? 'bg-red-500' : 'bg-green-500'}`} />}
                </div>
                {(sidebarExpanded || mobileMenuOpen) && <span className="text-[10px] font-bold text-slate-400 uppercase tracking-wider">{t.cloudSync}</span>}
              </div>
              {(sidebarExpanded || mobileMenuOpen) && isSyncing && <RefreshCw size={12} className="animate-spin text-indigo-400" />}
            </div>
            {(sidebarExpanded || mobileMenuOpen) && (
              <div className="mt-3 space-y-2 animate-in fade-in duration-500">
                <div className={`flex items-center gap-2 text-[10px] font-bold ${syncStatus === 'error' ? 'text-red-400' : 'text-green-400'}`}>{syncStatus === 'error' ? t.syncFailed : (sheetUrl ? t.connected : t.notConfigured)}</div>
                {sheetUrl && <button onClick={() => handleSync('pull')} disabled={isSyncing} className="w-full py-1.5 bg-slate-700 hover:bg-slate-600 disabled:opacity-50 rounded-lg text-[9px] font-bold uppercase tracking-widest transition-colors flex items-center justify-center gap-2"><RefreshCw size={10} className={isSyncing ? "animate-spin" : ""} />{t.syncNow}</button>}
              </div>
            )}
          </div>
        </div>
        <div className="p-4 mt-auto border-t border-slate-800">
          <button onClick={handleLogout} className={`flex items-center gap-4 text-slate-400 hover:text-white transition-colors w-full px-4 py-3 rounded-2xl ${(sidebarExpanded || mobileMenuOpen) ? '' : 'justify-center'}`}><LogOut size={20} />{(sidebarExpanded || mobileMenuOpen) && <span className="font-medium text-sm animate-in fade-in">{t.signOut}</span>}</button>
        </div>
      </aside>
      <main className="flex-1 flex flex-col h-screen overflow-hidden">
        <header className="bg-white/80 backdrop-blur-md border-b border-slate-200 px-4 md:px-8 py-4 flex items-center justify-between z-30 shrink-0">
          <div className="flex items-center gap-3">
            <button onClick={() => setMobileMenuOpen(true)} className="p-2 bg-slate-100 rounded-xl md:hidden text-slate-600 hover:bg-indigo-50 transition-all"><Menu size={20} /></button>
            <h2 className="text-lg md:text-2xl font-black text-slate-800 tracking-tight capitalize truncate">{activeTab === 'settings' ? t.settings : activeTab === 'dashboard' ? t.dashboard : t.inventory}</h2>
          </div>
          <div className="flex items-center gap-2">
            <button onClick={generateInsights} disabled={isAnalyzing} className="p-2.5 bg-indigo-50 text-indigo-700 rounded-xl hover:bg-indigo-100 transition-all border border-indigo-100 md:px-4 md:py-2.5 md:flex md:items-center md:gap-2">{isAnalyzing ? <Loader2 className="animate-spin" size={16} /> : <Sparkles size={16} />}<span className="hidden md:inline font-bold text-sm">{t.aiInsights}</span></button>
            <div className="hidden sm:flex items-center gap-2">
              <button onClick={toggleLanguage} className="p-2.5 bg-slate-50 text-slate-600 rounded-xl hover:bg-slate-200 transition-colors border border-slate-200"><Languages size={18} /></button>
              <div className="h-6 w-px bg-slate-200 mx-1"></div>
              <button onClick={() => storageService.exportToCSV(devices)} className="p-2.5 bg-slate-50 text-slate-600 rounded-xl hover:bg-slate-200 transition-colors border border-slate-200"><Download size={18} /></button>
              <button onClick={() => fileInputRef.current?.click()} className="p-2.5 bg-slate-50 text-slate-600 rounded-xl hover:bg-slate-200 transition-colors border border-slate-200"><Upload size={18} /></button>
              <input type="file" ref={fileInputRef} onChange={handleImportCSV} accept=".csv" className="hidden" />
            </div>
            <button onClick={() => { setEditingDevice(null); setIsFormOpen(true); }} className="p-2.5 bg-indigo-600 text-white rounded-xl shadow-lg shadow-indigo-500/20 hover:bg-indigo-700 md:px-6 md:py-2.5 md:flex md:items-center md:gap-2"><Plus size={18} /><span className="hidden md:inline font-bold text-sm">{t.addDevice}</span></button>
          </div>
        </header>
        <div className="flex-1 overflow-y-auto p-4 md:p-8">
          <div className="max-w-7xl mx-auto space-y-8">
            {aiInsights && (
              <div className="bg-white p-6 md:p-8 rounded-[32px] border-2 border-indigo-100 shadow-xl shadow-indigo-600/5 animate-in fade-in slide-in-from-top-4 relative">
                <button onClick={() => setAiInsights(null)} className="absolute top-4 right-4 p-2 text-slate-400 hover:bg-slate-100 rounded-full"><X size={20} /></button>
                <div className="flex gap-4">
                  <div className="p-3 bg-indigo-600 rounded-2xl text-white shrink-0"><Sparkles size={24} /></div>
                  <div className="space-y-2"><h3 className="font-black text-slate-900 text-lg">{t.aiInsights}</h3><p className="text-slate-600 text-sm md:text-base leading-relaxed whitespace-pre-line">{aiInsights}</p></div>
                </div>
              </div>
            )}
            {activeTab === 'dashboard' && <Dashboard devices={devices} lang={lang} onExpiringClick={handleShowExpiring} />}
            {activeTab === 'inventory' && <DeviceTable devices={devices} onEdit={(d) => { setEditingDevice(d); setIsFormOpen(true); }} onDelete={deleteDevice} onViewHistory={(d) => setHistoryDevice(d)} lang={lang} externalExpiringFilter={externalExpiringFilter} />}
            {activeTab === 'settings' && (
              <div className="max-w-2xl mx-auto space-y-6">
                <div className="bg-white p-6 md:p-8 rounded-3xl border border-slate-200 shadow-sm space-y-6">
                  <div className="flex items-center gap-4"><Cloud className="text-indigo-600" size={24} /><div><h3 className="font-bold text-slate-800">{t.cloudSync}</h3><p className="text-xs text-slate-500">Google Sheets Web App URL</p></div></div>
                  <input type="text" className="w-full px-5 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none text-xs font-mono" value={sheetUrl} onChange={(e) => { setSheetUrl(e.target.value); storageService.saveSettings({ sheetUrl: e.target.value }); }} />
                </div>
                <div className="bg-white p-6 md:p-8 rounded-3xl border border-slate-200 shadow-sm space-y-6">
                  <div className="flex items-center gap-4"><Key className="text-slate-900" size={24} /><div><h3 className="font-bold text-slate-800">{t.securitySettings}</h3><p className="text-xs text-slate-500">{t.changePass}</p></div></div>
                  <form onSubmit={handleChangePassword} className="space-y-4">
                    <input required type="password" placeholder={t.currentPass} value={passCurrent} onChange={e => setPassCurrent(e.target.value)} className="w-full px-5 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none text-sm" />
                    <input required type="password" placeholder={t.newPass} value={passNew} onChange={e => setPassNew(e.target.value)} className="w-full px-5 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none text-sm" />
                    <input required type="password" placeholder={t.confirmPass} value={passConfirm} onChange={e => setPassConfirm(e.target.value)} className="w-full px-5 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none text-sm" />
                    {passStatus && <div className={`p-3 rounded-lg text-xs font-bold ${passStatus.type === 'success' ? 'bg-green-50 text-green-700' : 'bg-red-50 text-red-700'}`}>{passStatus.msg}</div>}
                    <button type="submit" className="w-full py-3 bg-slate-900 text-white rounded-xl font-bold text-sm hover:bg-black transition-all"> {t.updatePass} </button>
                  </form>
                </div>
              </div>
            )}
          </div>
        </div>
      </main>
      {isFormOpen && <DeviceForm device={editingDevice} onSave={saveDevice} onClose={() => setIsFormOpen(false)} lang={lang} />}
      {historyDevice && <HistoryModal device={historyDevice} onClose={() => setHistoryDevice(null)} lang={lang} />}
    </div>
  );
};

const SidebarLink = ({ active, onClick, icon, label, expanded }: any) => (
  <button onClick={onClick} className={`flex items-center gap-4 w-full px-4 py-3.5 rounded-2xl transition-all duration-300 group relative ${active ? 'bg-indigo-600 text-white font-bold shadow-lg shadow-indigo-600/20' : 'text-slate-400 hover:bg-slate-800 hover:text-slate-200'} ${!expanded && 'justify-center'}`}>
    <div className={`${active ? 'text-white' : 'text-slate-500 group-hover:text-indigo-400'} transition-colors shrink-0`}>{icon}</div>
    {expanded && <span className="text-sm tracking-wide truncate animate-in fade-in slide-in-from-left-2">{label}</span>}
    {!expanded && <div className="absolute left-full ml-2 px-3 py-2 bg-slate-800 text-white text-[10px] font-bold uppercase rounded-lg opacity-0 group-hover:opacity-100 pointer-events-none transition-opacity whitespace-nowrap z-50">{label}</div>}
  </button>
);

export default App;

import React, { useState, useEffect } from 'react';
import { Device, DeviceType } from '../types';
import { translations } from '../translations';
import { Search, Edit2, Trash2, Filter, History, AlertTriangle } from 'lucide-react';
import { LIFESPAN_MAP } from './Dashboard';

interface Props {
  devices: Device[];
  onEdit: (device: Device) => void;
  onDelete: (id: string) => void;
  onViewHistory: (device: Device) => void;
  lang: 'en' | 'vi';
  externalExpiringFilter?: boolean;
}

const DeviceTable: React.FC<Props> = ({ devices, onEdit, onDelete, onViewHistory, lang, externalExpiringFilter }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [typeFilter, setTypeFilter] = useState<string>('All');
  const [statusFilter, setStatusFilter] = useState<string>('All');
  const [showOnlyExpiring, setShowOnlyExpiring] = useState(false);

  const t = translations[lang];

  useEffect(() => {
    if (externalExpiringFilter) {
      setShowOnlyExpiring(true);
      setTypeFilter('All');
      setStatusFilter('All');
    }
  }, [externalExpiringFilter]);

  const filteredDevices = devices.filter(d => {
    const matchesSearch = 
      (d.pcName || "").toLowerCase().includes(searchTerm.toLowerCase()) ||
      d.manufacturer.toLowerCase().includes(searchTerm.toLowerCase()) ||
      d.model.toLowerCase().includes(searchTerm.toLowerCase()) ||
      d.serialNumber.toLowerCase().includes(searchTerm.toLowerCase()) ||
      d.assignedTo.toLowerCase().includes(searchTerm.toLowerCase());

    const matchesType = typeFilter === 'All' || d.type === typeFilter;
    const matchesStatus = statusFilter === 'All' || d.status === statusFilter;

    let matchesExpiring = true;
    if (showOnlyExpiring) {
      if (d.purchaseDate) {
        const today = new Date();
        const alertThreshold = new Date();
        alertThreshold.setDate(today.getDate() + 60);

        const purchaseDate = new Date(d.purchaseDate);
        const lifespanYears = LIFESPAN_MAP[d.type] || 5;
        const lifecycleExpiry = new Date(purchaseDate);
        lifecycleExpiry.setFullYear(purchaseDate.getFullYear() + lifespanYears);
        matchesExpiring = lifecycleExpiry < alertThreshold;
      } else {
        matchesExpiring = false;
      }
    }

    return matchesSearch && matchesType && matchesStatus && matchesExpiring;
  });

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'Available': return 'bg-green-100 text-green-700';
      case 'Assigned': return 'bg-blue-100 text-blue-700';
      case 'Maintenance': return 'bg-amber-100 text-amber-700';
      case 'Retired': return 'bg-slate-200 text-slate-700';
      default: return 'bg-slate-100 text-slate-700';
    }
  };

  return (
    <div className="bg-white rounded-3xl shadow-sm border border-slate-200 overflow-hidden">
      <div className="p-6 border-b border-slate-100 space-y-4">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="relative flex-1 max-w-md">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text"
              placeholder={t.searchPlaceholder}
              className="w-full pl-12 pr-6 py-3 bg-slate-50 border border-slate-200 rounded-2xl focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 outline-none text-sm transition-all"
              value={searchTerm}
              onChange={e => setSearchTerm(e.target.value)}
            />
          </div>

          <div className="flex flex-wrap items-center gap-3">
            <div className="flex items-center gap-2">
              <Filter size={16} className="text-slate-400" />
              <select 
                className="bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-[10px] font-bold uppercase tracking-widest outline-none cursor-pointer"
                value={typeFilter}
                onChange={e => { setTypeFilter(e.target.value); if(e.target.value !== 'All') setShowOnlyExpiring(false); }}
              >
                <option value="All">{t.allTypes}</option>
                {Object.values(DeviceType).map(v => <option key={v} value={v}>{v}</option>)}
              </select>
            </div>

            <div className="flex items-center gap-2">
              <select 
                className="bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-[10px] font-bold uppercase tracking-widest outline-none cursor-pointer"
                value={statusFilter}
                onChange={e => { setStatusFilter(e.target.value); if(e.target.value !== 'All') setShowOnlyExpiring(false); }}
              >
                <option value="All">{t.allStatus}</option>
                <option value="Available">{t.available}</option>
                <option value="Assigned">{t.assigned}</option>
                <option value="Maintenance">{t.maintenance}</option>
                <option value="Retired">{t.retired}</option>
              </select>
            </div>

            <button 
              onClick={() => setShowOnlyExpiring(!showOnlyExpiring)}
              className={`flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-bold uppercase tracking-widest transition-all ${showOnlyExpiring ? 'bg-amber-100 text-amber-700 border border-amber-200' : 'bg-slate-50 text-slate-400 border border-slate-200 hover:bg-slate-100'}`}
            >
              <AlertTriangle size={14} />
              {t.expiringSoon}
            </button>
          </div>
        </div>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-left border-collapse min-w-[1200px]">
          <thead>
            <tr className="bg-slate-50/50">
              <th className="px-6 py-5 text-xs font-bold text-slate-400 uppercase tracking-wider">{t.pcName}</th>
              <th className="px-6 py-5 text-xs font-bold text-slate-400 uppercase tracking-wider">{t.deviceType}</th>
              <th className="px-6 py-5 text-xs font-bold text-slate-400 uppercase tracking-wider">{t.manufacturer}</th>
              <th className="px-6 py-5 text-xs font-bold text-slate-400 uppercase tracking-wider">{t.model}</th>
              <th className="px-6 py-5 text-xs font-bold text-slate-400 uppercase tracking-wider">{t.serial}</th>
              <th className="px-6 py-5 text-xs font-bold text-slate-400 uppercase tracking-wider">{t.dates}</th>
              <th className="px-6 py-5 text-xs font-bold text-slate-400 uppercase tracking-wider">{t.handoverDate}</th>
              <th className="px-6 py-5 text-xs font-bold text-slate-400 uppercase tracking-wider">{t.assignee}</th>
              <th className="px-6 py-5 text-xs font-bold text-slate-400 uppercase tracking-wider">{t.status}</th>
              <th className="px-6 py-5 text-xs font-bold text-slate-400 uppercase tracking-wider text-right">{t.actions}</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {filteredDevices.map(device => (
              <tr key={device.id} className="hover:bg-slate-50/50 transition-colors group">
                <td className="px-6 py-5">
                  <span className="text-sm font-bold text-slate-900">{device.pcName || '---'}</span>
                </td>
                <td className="px-6 py-5">
                  <span className="text-[10px] font-bold text-indigo-600 bg-indigo-50 px-2.5 py-1 rounded-lg uppercase tracking-wider">
                    {device.type}
                  </span>
                </td>
                <td className="px-6 py-5">
                  <span className="text-sm font-semibold text-slate-700">{device.manufacturer}</span>
                </td>
                <td className="px-6 py-5">
                  <span className="text-sm text-slate-600">{device.model}</span>
                </td>
                <td className="px-6 py-5">
                  <code className="text-[11px] font-mono bg-slate-100 text-slate-700 px-2 py-1.5 rounded-lg border border-slate-200/50">{device.serialNumber}</code>
                </td>
                <td className="px-6 py-5">
                  <div className="flex flex-col text-[11px] font-medium text-slate-600">
                    <span className="whitespace-nowrap">M: {device.purchaseDate}</span>
                    <span className="whitespace-nowrap text-indigo-600">BH: {device.warrantyExpiry}</span>
                  </div>
                </td>
                <td className="px-6 py-5 text-sm text-slate-600">
                  {device.handoverDate || '---'}
                </td>
                <td className="px-6 py-5 text-sm font-semibold text-slate-800">
                  {device.assignedTo || t.unassigned}
                </td>
                <td className="px-6 py-5">
                  <span className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase tracking-wider ${getStatusColor(device.status)}`}>
                    {device.status}
                  </span>
                </td>
                <td className="px-6 py-5 text-right">
                  <div className="flex items-center justify-end gap-1">
                    <button 
                      onClick={() => onViewHistory(device)} 
                      className="p-2.5 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-xl transition-all" 
                      title={t.handoverHistory}
                    >
                      <History size={16}/>
                    </button>
                    <button 
                      onClick={() => onEdit(device)} 
                      className="p-2.5 text-slate-400 hover:text-slate-900 hover:bg-slate-100 rounded-xl transition-all" 
                      title={t.editDevice}
                    >
                      <Edit2 size={16}/>
                    </button>
                    <button 
                      onClick={() => onDelete(device.id)} 
                      className="p-2.5 text-slate-400 hover:text-red-600 hover:bg-red-50 rounded-xl transition-all" 
                      title="Delete"
                    >
                      <Trash2 size={16}/>
                    </button>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        {filteredDevices.length === 0 && (
          <div className="py-20 text-center text-slate-400">
            <div className="text-sm font-medium">Không tìm thấy thiết bị nào phù hợp.</div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DeviceTable;

import React, { useState, useEffect, useRef } from 'react';
import { Device, DeviceType, HistoryEntry } from './types';
import { storageService } from './services/storageService';
import { geminiService } from './services/geminiService';
import { translations } from './translations';
import Dashboard from './components/Dashboard';
import DeviceTable from './components/DeviceTable';
import DeviceForm from './components/DeviceForm';
import HistoryModal from './components/HistoryModal';
import { 
  Plus, Download, Upload, Sparkles, LayoutDashboard, 
  Database, LogOut, Loader2, CheckCircle2, Cloud, 
  Settings as SettingsIcon, AlertCircle, RefreshCw, Languages,
  Share2, Copy, Check, Lock, ShieldCheck, Key, X, Menu, ChevronLeft, ChevronRight,
  Info, AlertTriangle
} from 'lucide-react';

interface Toast {
  id: string;
  message: string;
  type: 'success' | 'error' | 'info' | 'warning';
}

const App: React.FC = () => {
  const [lang, setLang] = useState<'en' | 'vi'>('vi');
  const [isAuthorized, setIsAuthorized] = useState<boolean>(false);
  const [authInput, setAuthInput] = useState('');
  const [authError, setAuthError] = useState(false);
  const [masterKey, setMasterKey] = useState<string>('');

  // States cho Sidebar
  const [sidebarExpanded, setSidebarExpanded] = useState(true);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  // States cho lọc ngoại vi
  const [externalExpiringFilter, setExternalExpiringFilter] = useState(false);

  // States cho Toasts
  const [toasts, setToasts] = useState<Toast[]>([]);

  // States cho đổi mật khẩu
  const [passCurrent, setPassCurrent] = useState('');
  const [passNew, setPassNew] = useState('');
  const [passConfirm, setPassConfirm] = useState('');
  const [passStatus, setPassStatus] = useState<{type: 'success' | 'error', msg: string} | null>(null);

  const [devices, setDevices] = useState<Device[]>([]);
  const [activeTab, setActiveTab] = useState<'dashboard' | 'inventory' | 'settings'>('dashboard');
  const [isFormOpen, setIsFormOpen] = useState(false);
  const [editingDevice, setEditingDevice] = useState<Device | null>(null);
  const [historyDevice, setHistoryDevice] = useState<Device | null>(null);
  const [aiInsights, setAiInsights] = useState<string | null>(null);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isSyncing, setIsSyncing] = useState(false);
  const [sheetUrl, setSheetUrl] = useState<string>(storageService.getSettings().sheetUrl);
  const [syncStatus, setSyncStatus] = useState<'idle' | 'success' | 'error'>('idle');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const t = translations[lang];

  const addToast = (message: string, type: Toast['type'] = 'info') => {
    const id = Math.random().toString(36).substr(2, 9);
    setToasts(prev => [...prev, { id, message, type }]);
    setTimeout(() => {
      setToasts(prev => prev.filter(t => t.id !== id));
    }, 4000);
  };

  const toggleLanguage = () => {
    setLang(prev => prev === 'en' ? 'vi' : 'en');
    addToast(lang === 'vi' ? "Switched to English" : "Đã đổi sang Tiếng Việt", "info");
  };

  const generateInsights = async () => {
    if (devices.length === 0) return;
    setIsAnalyzing(true);
    try {
      const result = await geminiService.analyzeInventory(devices);
      setAiInsights(result);
      addToast(lang === 'vi' ? "Đã cập nhật phân tích AI" : "AI Insights updated", "success");
    } catch (error) {
      setAiInsights(lang === 'vi' ? "Phân tích AI thất bại." : "AI Analysis failed.");
      addToast("AI Error", "error");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault();
    setAuthError(false);
    try {
      const data = await storageService.getDevicesSecure(authInput);
      setDevices(data);
      setMasterKey(authInput);
      setIsAuthorized(true);
      addToast(lang === 'vi' ? "Truy cập thành công" : "Access granted", "success");
    } catch (err) {
      if (!localStorage.getItem('device_master_encrypted') && authInput === '123456') {
        setMasterKey(authInput);
        setIsAuthorized(true);
        addToast(lang === 'vi' ? "Chào mừng bạn!" : "Welcome!", "success");
        return;
      }
      setAuthError(true);
      addToast("Invalid Key", "error");
    }
  };

  const handleLogout = () => {
    setIsAuthorized(false);
    setMasterKey('');
    setDevices([]);
    setMobileMenuOpen(false);
    addToast(lang === 'vi' ? "Đã đăng xuất" : "Signed out", "info");
  };

  const handleChangePassword = async (e: React.FormEvent) => {
    e.preventDefault();
    if (passCurrent !== masterKey) {
      setPassStatus({ type: 'error', msg: t.wrongCurrentPass });
      addToast(t.wrongCurrentPass, "error");
      return;
    }
    if (passNew !== passConfirm) {
      setPassStatus({ type: 'error', msg: t.passMismatch });
      addToast(t.passMismatch, "error");
      return;
    }
    try {
      await storageService.saveDevicesSecure(devices, passNew);
      setMasterKey(passNew);
      setPassStatus({ type: 'success', msg: t.passSuccess });
      addToast(t.passSuccess, "success");
      setPassCurrent(''); setPassNew(''); setPassConfirm('');
    } catch (err) {
      setPassStatus({ type: 'error', msg: "Update failed" });
      addToast("Update failed", "error");
    }
  };

  const handleSync = async (direction: 'pull' | 'push', updatedDevices?: Device[]) => {
    if (!sheetUrl || !masterKey) return;
    setIsSyncing(true);
    try {
      const targetData = updatedDevices || devices;
      const result = await storageService.syncWithGoogleSheet(sheetUrl, masterKey, direction === 'push' ? targetData : undefined);
      if (direction === 'pull' && result) {
        setDevices(result);
        await storageService.saveDevicesSecure(result, masterKey);
      }
      setSyncStatus('success');
      addToast(direction === 'push' ? (lang === 'vi' ? "Đã đẩy dữ liệu lên mây" : "Pushed to cloud") : (lang === 'vi' ? "Đã đồng bộ từ mây" : "Pulled from cloud"), "success");
    } catch (error) {
      setSyncStatus('error');
      addToast("Sync failed", "error");
    } finally {
      setIsSyncing(false);
    }
  };

  const handleImportCSV = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;

    addToast(lang === 'vi' ? "Đang xử lý file..." : "Processing file...", "info");

    const reader = new FileReader();
    reader.onload = async (e) => {
      const text = e.target?.result as string;
      try {
        const imported = storageService.parseCSV(text);
        if (imported.length === 0) {
          addToast(t.importEmpty, "warning");
          return;
        }

        const currentSerials = new Set(devices.map(d => d.serialNumber.toLowerCase()));
        const newDevices = imported.filter(d => !currentSerials.has(d.serialNumber.toLowerCase()));

        if (newDevices.length === 0) {
          addToast(t.importNoNew, "warning");
          return;
        }

        const updated = [...devices, ...newDevices];
        setDevices(updated);
        await storageService.saveDevicesSecure(updated, masterKey);

        addToast(t.importSuccess.replace('{count}', newDevices.length.toString()), "success");

        if (sheetUrl) handleSync('push', updated);
      } catch (err) {
        console.error(err);
        addToast(t.importError, "error");
      }
    };
    reader.onerror = () => addToast("FileReader Error", "error");
    reader.readAsText(file);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const saveDevice = async (newDeviceData: Device) => {
    let updatedDevices: Device[];
    const now = new Date().toISOString().split('T')[0];
    if (editingDevice) {
      const isAssigneeChanged = editingDevice.assignedTo !== newDeviceData.assignedTo;
      const isStatusChanged = editingDevice.status !== newDeviceData.status;
      const newHistory = [...(newDeviceData.history || [])];
      if (isAssigneeChanged || isStatusChanged) {
        newHistory.push({
          id: Math.random().toString(36).substr(2, 9),
          assignee: newDeviceData.assignedTo || t.unassigned,
          date: newDeviceData.handoverDate || now,
          notes: isAssigneeChanged ? (lang === 'vi' ? `Bàn giao mới` : 'New handover') : `Cập nhật: ${newDeviceData.status}`
        });
      }
      updatedDevices = devices.map(d => d.id === newDeviceData.id ? { ...newDeviceData, history: newHistory } : d);
      addToast(lang === 'vi' ? "Đã cập nhật thiết bị" : "Device updated", "success");
    } else {
      updatedDevices = [...devices, { ...newDeviceData, history: [{ id: 'init', assignee: 'Stock', date: now, notes: 'Khởi tạo' }] }];
      addToast(lang === 'vi' ? "Đã thêm thiết bị mới" : "New device added", "success");
    }
    setDevices(updatedDevices);
    await storageService.saveDevicesSecure(updatedDevices, masterKey);
    setIsFormOpen(false);
    if (sheetUrl) handleSync('push', updatedDevices);
  };

  const deleteDevice = async (id: string) => {
    if (window.confirm(lang === 'vi' ? 'Xóa thiết bị này?' : 'Delete this device?')) {
      const updated = devices.filter(d => d.id !== id);
      setDevices(updated);
      await storageService.saveDevicesSecure(updated, masterKey);
      addToast(lang === 'vi' ? "Đã xóa thiết bị" : "Device deleted", "info");
      if (sheetUrl) handleSync('push', updated);
    }
  };

  const handleShowExpiring = () => {
    setExternalExpiringFilter(true);
    setActiveTab('inventory');
    setTimeout(() => setExternalExpiringFilter(false), 500);
  };

  if (!isAuthorized) {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center p-6 relative overflow-hidden">
        {/* Toast Container for Login Page */}
        <ToastContainer toasts={toasts} />
        <div className="absolute top-0 -left-20 w-96 h-96 bg-indigo-600/20 rounded-full blur-[100px]"></div>
        <div className="w-full max-w-md bg-slate-900/50 backdrop-blur-2xl p-10 rounded-[40px] border border-slate-800 shadow-2xl relative z-10">
          <div className="flex flex-col items-center mb-8 text-center">
            <div className="w-20 h-20 bg-white rounded-2xl flex items-center justify-center overflow-hidden mb-6 shadow-xl">
              <img src="https://d2nyjryheal9w7.cloudfront.net/610a5b0dbd9b2500172ecee5/%E7%A8%B2%E7%95%91%E7%94%A3%E6%A5%AD%E3%83%AD%E3%82%B4%20(1).png" alt="Logo" className="w-full h-full object-contain p-2" />
            </div>
            <h1 className="text-2xl font-black text-white mb-2 tracking-tight">{t.loginTitle}</h1>
            <p className="text-slate-400 text-sm">{t.loginDesc}</p>
          </div>
          <form onSubmit={handleLogin} className="space-y-6">
            <input 
              type="password" 
              placeholder={t.enterKey} 
              className="w-full pl-6 pr-6 py-4 bg-slate-800/50 border border-slate-700 rounded-2xl text-white outline-none focus:ring-4 focus:ring-indigo-500/20 focus:border-indigo-500 transition-all font-mono tracking-widest text-center"
              value={authInput}
              onChange={(e) => setAuthInput(e.target.value)}
              autoFocus
            />
            {authError && <div className="text-red-400 text-xs font-bold text-center">Mã khóa không đúng.</div>}
            <button type="submit" className="w-full py-4 bg-indigo-600 hover:bg-indigo-700 text-white rounded-2xl font-bold shadow-xl shadow-indigo-500/20 transition-all flex items-center justify-center gap-2">
              <ShieldCheck size={18} /> {t.unlock}
            </button>
          </form>
          <div className="mt-8 pt-8 border-t border-slate-800 flex justify-center">
             <button onClick={toggleLanguage} className="text-[10px] font-bold uppercase tracking-widest text-slate-500 hover:text-indigo-400">
               {lang === 'en' ? 'Tiếng Việt' : 'English'}
             </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex min-h-screen bg-slate-50 text-slate-900 overflow-hidden">
      <ToastContainer toasts={toasts} />
      {mobileMenuOpen && (
        <div className="fixed inset-0 bg-slate-950/60 backdrop-blur-sm z-40 md:hidden transition-opacity duration-300" onClick={() => setMobileMenuOpen(false)} />
      )}
      <aside className={`fixed inset-y-0 left-0 z-50 bg-slate-900 text-slate-300 transition-all duration-500 ease-in-out flex flex-col ${sidebarExpanded ? 'w-72' : 'w-20'} ${mobileMenuOpen ? 'translate-x-0 w-72' : '-translate-x-full md:translate-x-0'} md:relative md:flex`}>
        <button onClick={() => setSidebarExpanded(!sidebarExpanded)} className="hidden md:flex absolute -right-3 top-20 w-6 h-6 bg-indigo-600 rounded-full items-center justify-center text-white border-2 border-slate-900 hover:bg-indigo-50 transition-all z-10">
          {sidebarExpanded ? <ChevronLeft size={14} /> : <ChevronRight size={14} />}
        </button>
        <div className={`p-6 mb-4 flex items-center gap-3 overflow-hidden ${(!sidebarExpanded && !mobileMenuOpen) && 'justify-center'}`}>
          <div className="min-w-[40px] w-10 h-10 bg-white rounded-xl flex items-center justify-center overflow-hidden border border-slate-700 shrink-0">
            <img src="https://d2nyjryheal9w7.cloudfront.net/610a5b0dbd9b2500172ecee5/%E7%A8%B2%E7%95%91%E7%94%A3%E6%A5%AD%E3%83%AD%E3%82%B4%20(1).png" alt="Logo" className="w-full h-full object-contain p-1" />
          </div>
          {(sidebarExpanded || mobileMenuOpen) && (
            <div className="truncate whitespace-nowrap animate-in fade-in slide-in-from-left-2">
              <h1 className="font-bold text-white text-base leading-tight">Device Master</h1>
              <p className="text-[9px] text-indigo-400 font-bold uppercase tracking-widest">{t.subName}</p>
            </div>
          )}
        </div>
        <nav className="flex-1 px-3 space-y-2">
          <SidebarLink active={activeTab === 'dashboard'} onClick={() => { setActiveTab('dashboard'); setMobileMenuOpen(false); }} icon={<LayoutDashboard size={20} />} label={t.dashboard} expanded={sidebarExpanded || mobileMenuOpen} />
          <SidebarLink active={activeTab === 'inventory'} onClick={() => { setActiveTab('inventory'); setMobileMenuOpen(false); }} icon={<Database size={20} />} label={t.inventory} expanded={sidebarExpanded || mobileMenuOpen} />
          <SidebarLink active={activeTab === 'settings'} onClick={() => { setActiveTab('settings'); setMobileMenuOpen(false); }} icon={<SettingsIcon size={20} />} label={t.settings} expanded={sidebarExpanded || mobileMenuOpen} />
        </nav>
        <div className={`mt-4 px-3 mb-4 ${(sidebarExpanded || mobileMenuOpen) ? 'block' : 'flex justify-center'}`}>
          <div className={`bg-slate-800/50 rounded-2xl border border-slate-700/50 transition-all duration-300 ${ (sidebarExpanded || mobileMenuOpen) ? 'p-4' : 'p-2'}`}>
            <div className="flex items-center justify-between gap-2">
              <div className="flex items-center gap-2">
                <div className="relative">
