            {activeTab === 'inventory' && <DeviceTable devices={devices} onEdit={(d) => { setEditingDevice(d); setIsFormOpen(true); }} onDelete={deleteDevice} onViewHistory={(d) => setHistoryDevice(d)} lang={lang} externalExpiringFilter={externalExpiringFilter} />}
