// --- CRYPTO & STORAGE SERVICE ---
const cryptoUtils = {
  deriveKey: async (password: string, salt: Uint8Array) => {
    const encoder = new TextEncoder();
    const baseKey = await crypto.subtle.importKey('raw', encoder.encode(password), 'PBKDF2', false, ['deriveKey']);
    return crypto.subtle.deriveKey({ name: 'PBKDF2', salt, iterations: 100000, hash: 'SHA-256' }, baseKey, { name: 'AES-GCM', length: 256 }, false, ['encrypt', 'decrypt']);
  },
  encrypt: async (data: string, password: string) => {
    const salt = crypto.getRandomValues(new Uint8Array(16));
    const iv = crypto.getRandomValues(new Uint8Array(12));
    const key = await cryptoUtils.deriveKey(password, salt);
    const encoder = new TextEncoder();
    const encrypted = await crypto.subtle.encrypt({ name: 'AES-GCM', iv }, key, encoder.encode(data));
    const combined = new Uint8Array(salt.length + iv.length + encrypted.byteLength);
    combined.set(salt, 0); combined.set(iv, salt.length); combined.set(new Uint8Array(encrypted), salt.length + iv.length);
    return btoa(String.fromCharCode(...combined));
  },
  decrypt: async (encryptedBase64: string, password: string) => {
    try {
      const combined = new Uint8Array(atob(encryptedBase64).split('').map(c => c.charCodeAt(0)));
      const salt = combined.slice(0, 16); const iv = combined.slice(16, 28); const data = combined.slice(28);
      const key = await cryptoUtils.deriveKey(password, salt);
      const decrypted = await crypto.subtle.decrypt({ name: 'AES-GCM', iv }, key, data);
      return new TextDecoder().decode(decrypted);
    } catch (e) { throw new Error('Decryption failed'); }
  }
};

const storageService = {
  saveDevicesSecure: async (devices: Device[], password: string) => {
    const json = JSON.stringify(devices);
    const encrypted = await cryptoUtils.encrypt(json, password);
    localStorage.setItem('device_master_encrypted', encrypted);
  },
  getDevicesSecure: async (password: string): Promise<Device[]> => {
    const encrypted = localStorage.getItem('device_master_encrypted');
    if (!encrypted) return [];
    const decryptedJson = await cryptoUtils.decrypt(encrypted, password);
    return JSON.parse(decryptedJson);
  },
  getSettings: () => JSON.parse(localStorage.getItem('dm_settings') || '{"sheetUrl":""}'),
  saveSettings: (s: any) => localStorage.setItem('dm_settings', JSON.stringify(s)),
  exportToCSV: (devices: Device[]) => {
    const headers = ['PC Name', 'Type', 'Manufacturer', 'Model', 'Serial', 'Purchase Date', 'Warranty Expiry', 'Handover Date', 'Assigned To', 'Status'];
    const csv = [headers.join(','), ...devices.map(d => [d.pcName, d.type, d.manufacturer, d.model, d.serialNumber, d.purchaseDate, d.warrantyExpiry, d.handoverDate, d.assignedTo, d.status].map(v => `"${(v || '').toString().replace(/"/g, '""')}"`).join(','))].join('\n');
    const blob = new Blob(["\ufeff" + csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a'); link.href = URL.createObjectURL(blob); link.download = 'devices.csv'; link.click();
  },
  parseCSV: (text: string): Device[] => {
    const lines = text.split(/\r?\n/); if (lines.length < 2) return [];
    const result: Device[] = [];
    for (let i = 1; i < lines.length; i++) {
      const parts = lines[i].split(',').map(s => s.replace(/^"|"$/g, '').trim());
      if (parts.length >= 5) result.push({ id: Math.random().toString(36).substr(2, 9), pcName: parts[0], type: (parts[1] || 'Laptop') as any, manufacturer: parts[2], model: parts[3], serialNumber: parts[4], purchaseDate: parts[5], warrantyExpiry: parts[6], handoverDate: parts[7], assignedTo: parts[8], status: (parts[9] || 'Available') as any, history: [] });
    }
    return result;
  }
};

