      <span className="text-2xl font-black text-slate-900">{value}</span>
    </div>
    <div className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{title}</div>
    {subtitle && <div className="text-[9px] text-amber-600 mt-1 font-bold uppercase">{subtitle}</div>}
  </div>
);

const Dashboard = ({ devices, lang, onExpiringClick }: any) => {
  const t = translations[lang];
  const stats = useMemo(() => {
    const today = new Date(); const threshold = new Date(); threshold.setDate(today.getDate() + 60);
    const typeCounts: any = {}; let assigned = 0; let expiring = 0;
    devices.forEach(d => {
      typeCounts[d.type] = (typeCounts[d.type] || 0) + 1;
      if (d.status === 'Assigned') assigned++;
      if (d.purchaseDate) {
        const exp = new Date(d.purchaseDate); exp.setFullYear(exp.getFullYear() + (LIFESPAN_MAP[d.type] || 5));
        if (exp < threshold) expiring++;
      }
    });
    return { total: devices.length, assigned, expiring, typeData: Object.entries(typeCounts).map(([name, value]) => ({ name, value })) };
  }, [devices]);

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard icon={<Monitor size={20} className="text-indigo-600" />} title={t.totalAssets} value={stats.total} color="bg-white" />
        <StatCard icon={<CheckCircle size={20} className="text-green-600" />} title={t.assigned} value={stats.assigned} color="bg-white" />
        <StatCard icon={<AlertTriangle size={20} className="text-amber-600" />} title={t.expiringSoon} value={stats.expiring} subtitle={t.expiringSubtitle} color="bg-amber-50 border-amber-100" onClick={onExpiringClick} />
        <StatCard icon={<Smartphone size={20} className="text-slate-600" />} title={t.deviceTypes} value={stats.typeData.length} color="bg-white" />
      </div>
    </div>
  );
};

