const LIFESPAN_MAP: Record<string, number> = { [DeviceType.LAPTOP]: 4, [DeviceType.DESKTOP]: 5, [DeviceType.MOBILE]: 3, [DeviceType.TABLET]: 3, [DeviceType.OTHER]: 5 };

