                  <form className="space-y-4" onSubmit={async (e: any) => { e.preventDefault(); const n = e.target.newKey.value; const c = e.target.confirmKey.value; if (n !== c) { addToast(t.passMismatch, 'error'); return; } await storageService.saveDevicesSecure(devices, n); setMasterKey(n); addToast(t.passSuccess, 'success'); e.target.reset(); }}>
                    <input name="currentKey" required type="password" placeholder={t.currentPass} className="w-full px-5 py-3 bg-slate-50 rounded-xl outline-none text-sm"/>
                    <input name="newKey" required type="password" placeholder={t.newPass} className="w-full px-5 py-3 bg-slate-50 rounded-xl outline-none text-sm"/>
                    <input name="confirmKey" required type="password" placeholder={t.confirmPass} className="w-full px-5 py-3 bg-slate-50 rounded-xl outline-none text-sm"/>
                    <button type="submit" className="w-full py-4 bg-slate-900 text-white rounded-2xl font-bold hover:bg-black transition-all uppercase tracking-widest text-xs">{t.updatePass}</button>
                  </form>
                </div>
              </div>
            )}
          </div>
        </div>
      </main>

      {/* FORM MODAL */}
      {isFormOpen && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md flex items-center justify-center z-[200] p-4 overflow-y-auto">
          <div className="bg-white rounded-[40px] p-8 max-w-2xl w-full shadow-2xl animate-in zoom-in border border-slate-100 my-10">
            <div className="flex justify-between items-center mb-8"><h2 className="text-2xl font-black uppercase tracking-tight">{editingDevice ? t.editDevice : t.addDevice}</h2><button onClick={() => setIsFormOpen(false)}><X size={24}/></button></div>
            <form onSubmit={saveDevice} className="grid grid-cols-2 gap-4">
              <div className="col-span-2"><label className="text-[10px] font-black text-slate-400 uppercase ml-2">{t.pcName}</label><input name="pcName" required defaultValue={editingDevice?.pcName} className="w-full px-5 py-3 bg-slate-100 rounded-2xl outline-none font-bold" /></div>
              <div><label className="text-[10px] font-black text-slate-400 uppercase ml-2">{t.deviceType}</label><select name="type" defaultValue={editingDevice?.type} className="w-full px-5 py-3 bg-slate-100 rounded-2xl outline-none font-bold">{Object.values(DeviceType).map(v => <option key={v} value={v}>{v}</option>)}</select></div>
              <div><label className="text-[10px] font-black text-slate-400 uppercase ml-2">{t.status}</label><select name="status" defaultValue={editingDevice?.status} className="w-full px-5 py-3 bg-slate-100 rounded-2xl outline-none font-bold"><option value="Available">{t.available}</option><option value="Assigned">{t.assigned}</option><option value="Maintenance">{t.maintenance}</option><option value="Retired">{t.retired}</option></select></div>
              <div><label className="text-[10px] font-black text-slate-400 uppercase ml-2">{t.manufacturer}</label><input name="manufacturer" required defaultValue={editingDevice?.manufacturer} className="w-full px-5 py-3 bg-slate-100 rounded-2xl outline-none font-bold" /></div>
              <div><label className="text-[10px] font-black text-slate-400 uppercase ml-2">{t.model}</label><input name="model" required defaultValue={editingDevice?.model} className="w-full px-5 py-3 bg-slate-100 rounded-2xl outline-none font-bold" /></div>
              <div className="col-span-2"><label className="text-[10px] font-black text-slate-400 uppercase ml-2">{t.serial}</label><input name="serial" required defaultValue={editingDevice?.serialNumber} className="w-full px-5 py-3 bg-slate-100 rounded-2xl outline-none font-mono" /></div>
              <div><label className="text-[10px] font-black text-slate-400 uppercase ml-2">{t.assignee}</label><input name="assignee" defaultValue={editingDevice?.assignedTo} className="w-full px-5 py-3 bg-slate-100 rounded-2xl outline-none font-bold" /></div>
              <div><label className="text-[10px] font-black text-slate-400 uppercase ml-2">{t.handoverDate}</label><input type="date" name="handoverDate" defaultValue={editingDevice?.handoverDate} className="w-full px-5 py-3 bg-slate-100 rounded-2xl outline-none" /></div>
              <div><label className="text-[10px] font-black text-slate-400 uppercase ml-2">{t.purchaseDate}</label><input type="date" name="purchaseDate" defaultValue={editingDevice?.purchaseDate} className="w-full px-5 py-3 bg-slate-100 rounded-2xl outline-none" /></div>
              <div><label className="text-[10px] font-black text-slate-400 uppercase ml-2">{t.expiry}</label><input type="date" name="warrantyExpiry" defaultValue={editingDevice?.warrantyExpiry} className="w-full px-5 py-3 bg-slate-100 rounded-2xl outline-none" /></div>
              <div className="col-span-2"><label className="text-[10px] font-black text-slate-400 uppercase ml-2">{t.notes}</label><textarea name="notes" defaultValue={editingDevice?.notes} className="w-full px-5 py-3 bg-slate-100 rounded-2xl outline-none h-24" /></div>
              <div className="col-span-2 flex gap-4 mt-4"><button type="button" onClick={() => setIsFormOpen(false)} className="flex-1 py-4 bg-slate-100 rounded-2xl font-bold uppercase tracking-widest text-xs">Hủy</button><button type="submit" className="flex-1 py-4 bg-indigo-600 text-white rounded-2xl font-bold shadow-xl shadow-indigo-500/20 uppercase tracking-widest text-xs">Lưu máy</button></div>
            </form>
          </div>
        </div>
      )}

      {/* DELETE CONFIRM */}
      {deleteId && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-md flex items-center justify-center z-[300] p-4"><div className="bg-white rounded-[40px] p-8 max-w-sm w-full shadow-2xl animate-in zoom-in text-center space-y-6"><div className="w-20 h-20 bg-red-50 text-red-600 rounded-full flex items-center justify-center mx-auto"><Trash2 size={40}/></div><h3 className="text-xl font-black text-slate-900">Xác nhận xóa?</h3><p className="text-sm text-slate-500">Dữ liệu thiết bị sẽ bị xóa vĩnh viễn.</p><div className="flex gap-4"><button onClick={() => setDeleteId(null)} className="flex-1 py-3 bg-slate-100 rounded-2xl font-bold">Hủy</button><button onClick={async () => { const updated = devices.filter(x => x.id !== deleteId); setDevices(updated); await storageService.saveDevicesSecure(updated, masterKey); setDeleteId(null); addToast('Đã xóa', 'info'); }} className="flex-1 py-3 bg-red-600 text-white rounded-2xl font-bold">Xóa máy</button></div></div></div>
      )}

      {historyDevice && <HistoryModal device={historyDevice} onClose={() => setHistoryDevice(null)} lang={lang} />}

      {/* TOASTS */}
      <div className="fixed top-6 left-1/2 -translate-x-1/2 z-[400] space-y-2 w-full max-w-sm px-4">
        {toasts.map(t => (
          <div key={t.id} className={`px-6 py-4 rounded-2xl shadow-2xl border text-sm font-black uppercase tracking-widest animate-in slide-in-from-top-4 flex items-center gap-3 backdrop-blur-md ${t.type === 'success' ? 'bg-green-50/90 border-green-200 text-green-700' : t.type === 'error' ? 'bg-red-50/90 border-red-200 text-red-700' : 'bg-white/90 border-slate-200 text-slate-800'}`}>
            {t.type === 'success' ? <CheckCircle size={18}/> : t.type === 'error' ? <AlertCircle size={18}/> : <Info size={18}/>} {t.msg}
          </div>
        ))}
      </div>
    </div>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root')!);
root.render(<App />);
